// Üretilen dosya: tool/ozgun/uret.py. Sanat · Rönesans ve Barok sanatı ayrıntılı (orta).
const ozArt6Orta = <(String, String, List<String>, String)>[
  ('1401\'de Floransa Vaftizhanesi\'nin kuzey kapıları için açılan yarışmada adaylardan bronz bir deneme panosu istendi. Bu panoların konusu neydi?', 'İshak\'ın kurban edilişi', ['Nuh\'un gemisi', 'Davut ile Golyat\'ın dövüşü', 'Âdem ile Havva\'nın yaratılışı'], 'Yarışmacılardan Eski Ahit\'teki İbrahim\'in oğlu İshak\'ı kurban etmeye hazırlandığı sahneyi dörtyapraklı bir çerçeve içinde işlemeleri istendi. Ghiberti ile Brunelleschi\'nin panoları bugün Bargello\'dadır.'),
  ('1401 Vaftizhane kapısı yarışmasını Ghiberti\'ye kaptırdıktan sonra Roma\'da antik yapıları inceleyen ve ilgisini giderek mimarlık ile perspektife çeviren sanatçı kimdir?', 'Filippo Brunelleschi', ['Donatello di Niccolò di Betto Bardi', 'Jacopo della Quercia', 'Michelozzo'], 'Yarışmanın iki finalisti Ghiberti ile Brunelleschi\'ydi. Kaybeden Brunelleschi sonradan katedral kubbesi ve perspektif deneyleriyle ün kazandı.'),
  ('Ghiberti\'nin doğu kapıları (Cennet Kapıları), aynı ustanın daha önceki kuzey kapılarından kompozisyon bakımından en çok hangi yönüyle ayrılır?', 'Az sayıda büyük kare panoda perspektifli derin mekânlar kurması', ['Panoların tümünü yalnızca tahtadan oyması', 'Sahneleri her iki kapıda da aynı dörtyapraklı çerçevelere yerleştirip yalnız sayıyı artırması', 'Anlatıyı bırakıp yalnız süsleme motifleri kullanması'], 'Kuzey kapılarında 28 küçük dörtyapraklı çerçeve vardır. Doğu kapılarında ise on büyük kare pano ve bu panolarda perspektifle derinleşen mekânlar kullanılmıştır.'),
  ('Floransa\'daki Orsanmichele binasının dış nişlerine 15. yüzyıl başında yerleştirilen azize ve aziz heykellerini kimler ısmarlamıştır?', 'Kentin meslek loncaları', ['Medici bankası', 'Roma\'daki papalık', 'Floransa Katedrali\'nin yapı kurulu'], 'Her nişe bir lonca kendi koruyucu azizinin heykelini koydurdu. Loncalar arasındaki bu yarış Donatello, Ghiberti ve Nanni di Banco gibi ustalara önemli işler kazandırdı.'),
  ('Donatello\'nun boyalı ahşaptan yaptığı, oruçtan erimiş bedeni ve uzun keçeleşmiş saçlarıyla çölde tövbe eden bir azizeyi gösteren heykeli hangisidir?', 'Tövbekâr Mecdelli Meryem', ['Azize Cecilia', 'Sienalı Azize Katerina', 'Azize Barbara'], 'Bu geç dönem heykelde Donatello güzelliği değil yaşlılığı ve çileyi vurgular. Eser bugün Floransa\'daki Katedral Müzesi\'ndedir.'),
  ('Floransa Katedrali için şarkı söyleyip çalgı çalan çocukların kabartmalarıyla süslü iki koro balkonu (cantoria) yapılmıştır. Bunlardan birini Donatello yapmıştır. Diğerinin heykeltıraşı kimdir?', 'Luca della Robbia', ['Lorenzo Ghiberti', 'Nanni di Banco', 'Andrea del Verrocchio'], 'Luca della Robbia\'nın 1430\'larda yaptığı cantoria, Donatello\'nunkinin karşısına konmuştu. Luca daha sonra sırlı pişmiş toprak heykelleriyle ün kazandı.'),
  ('Donatello\'nun bronz \'Yudit ve Holofernes\' heykeli Medicilerin 1494\'te kentten kovulmasının ardından Medici sarayından Signoria Meydanı\'na taşınmıştır. Heykel bu yeni yerinde nasıl bir anlam kazanmıştır?', 'Zorbalığa karşı direnen cumhuriyetin simgesi olmuştur', ['Medicilerin kente bağışını anan bir anıt olmuştur', 'Papalıkla yapılan barışın işareti sayılmıştır', 'Loncaların ticari gücünü gösteren bir amblem olmuştur'], 'Zorbayı öldüren dul Yudit, tiranlığa karşı yurttaş erdemini simgeledi. Kaidesine cumhuriyetçi bir yazıt eklendiği bilinir.'),
  ('Brancacci Şapeli fresklerine Masaccio ile birlikte başlayan, ondan yaşça büyük ve daha zarif, Gotik etkili bir üslupla çalışan ressam kimdir?', 'Masolino da Panicale', ['Fra Angelico', 'Lorenzo Monaco', 'Paolo Uccello'], 'Masolino ve Masaccio şapelde yan yana çalıştılar. Masolino\'nun \'Âdem ile Havva\'nın Günahı\' sahnesi, girişin karşı yanındaki Masaccio\'nun \'Cennetten Kovuluş\'uyla sık sık karşılaştırılır.'),
  ('Karmelit keşişi olduğu hâlde rahibe Lucrezia Buti ile birlikte yaşayan ve bu birlikten doğan oğlu da tanınmış bir ressam olan Floransalı ressam kimdir?', 'Fra Filippo Lippi', ['Fra Angelico', 'Fra Bartolomeo della Porta', 'Lorenzo Monaco'], 'Fra Filippo Lippi, Cosimo de\' Medici\'nin desteğiyle papadan izin alarak Lucrezia ile evlenebildi. Oğulları Filippino Lippi de ressam oldu.'),
  ('Sandro Botticelli gençliğinde hangi ressamın atölyesinde yetişmiş ve onun zarif çizgisini, yumuşak Meryem tiplerini devralmıştır?', 'Fra Filippo Lippi', ['Domenico Ghirlandaio', 'Pietro Perugino', 'Piero della Francesca'], 'Botticelli\'nin ilk Meryem resimleri Fra Filippo Lippi\'nin kompozisyonlarına çok yakındır. Daha sonra ustasının oğlu Filippino Lippi de Botticelli\'nin yanında çalıştı.'),
  ('Piero della Francesca, Urbino Dükü Federico da Montefeltro\'yu çift portrede ve sunak resminde hep sol profilden gösterir. Bunun bilinen nedeni nedir?', 'Dükün bir turnuvada sağ gözünü yitirmiş olması', ['Sağ yanağındaki doğum lekesini gizleme isteği', 'Urbino yasalarının hükümdarı cepheden göstermeyi yasaklaması', 'Ressamın yalnızca aynaya bakarak çalışabilmesi'], 'Federico bir mızrak turnuvasında sağ gözünü ve burun kemiğinin bir parçasını kaybetmişti. Sol profil hem yarayı gizler hem de kırık burnun çarpıcı çizgisini gösterir.'),
  ('Milano\'daki Brera Pinakotek\'te bulunan Montefeltro Sunağı\'nda, deniz kabuğu biçimli nişin tepesinden bir ip ile sarkan beyaz, oval nesne nedir?', 'Devekuşu yumurtası', ['Cam bir küre', 'İnciden yapılmış bir gerdanlık', 'Bronz bir kandil'], 'Devekuşu yumurtası hem yaratılışı ve Meryem\'in kusursuz gebeliğini hem de Montefeltro hanedanının simgesini çağrıştırır. Kusursuz geometrisiyle Piero\'nun düzen tutkusunu da yansıtır.'),
  ('Matematikçi Luca Pacioli\'nin 1509\'da basılan \'De divina proportione\' kitabındaki çokyüzlü cisim çizimlerini hangi sanatçı yapmıştır?', 'Leonardo da Vinci', ['Albrecht Dürer', 'Piero della Francesca', 'Leon Battista Alberti'], 'Leonardo ile Pacioli Milano\'da Ludovico Sforza\'nın sarayında dost olmuşlardı. Leonardo kitap için içi boş ve dolu çokyüzlülerin altmışı aşkın çizimini hazırladı.'),
  ('Mantova Dük Sarayı\'ndaki Camera degli Sposi\'nin tavanında, gökyüzüne açılan yuvarlak bir boşluktan aşağı bakan kadınlar ve melekçikler gösterilir. Bu tavan sonraki sanat için neden önemlidir?', 'Aşağıdan yukarı bakış yanılsamasının ilk büyük tavan örneklerinden olması', ['Tavanı ilk kez tuval üzerine boyanıp yerine asılmış olması', 'Dinsel konuları saray odalarından ilk kez tümüyle çıkarıp yerine yalnız av sahneleri koyması', 'Yağlı boyanın freskte kullanıldığı ilk iş olması'], 'Mantegna\'nın oculus\'u, mimari bir açıklık yanılsamasını kısaltılmış figürlerle birleştirir. Correggio\'dan Barok tavan ressamlarına uzanan geleneğin öncüsü sayılır.'),
  ('Antonello da Messina\'nın Palermo\'daki \'Müjdelenen Meryem\' tablosunda melek hiç gösterilmez; Meryem bir elini izleyiciye doğru kaldırmış biçimde tek başına durur. Bu kompozisyon izleyiciyi nasıl konumlandırır?', 'İzleyiciyi görünmeyen meleğin yerine koyar', ['İzleyiciyi sahnenin dışında kalan bir yabancı yapar', 'İzleyiciyi Meryem\'in arkasında bir tanık yapar', 'İzleyiciyi ikinci bir aziz gibi kalabalığa katar'], 'Müjde sahnesi normalde iki figürle kurulur. Meleğin çıkarılması, Meryem\'in tepkisini doğrudan resmin önündeki kişiye yöneltir.'),
  ('Meryem\'in tahtta oturduğu, azizlerin onun çevresinde bölmesiz tek bir mekânda sessizce durduğu, Giovanni Bellini\'nin San Zaccaria sunağında da görülen sunak resmi türüne ne ad verilir?', 'Sacra conversazione', ['Pietà', 'Noli me tangere', 'Deesis'], '\'Kutsal sohbet\' anlamına gelen bu türde figürler ayrı panolara bölünmez. Ortak bir mimari mekânda bir arada, dingin bir topluluk oluştururlar.'),
  ('Dominiken vaiz Savonarola\'nın etkisiyle 1497\'de Floransa\'da aynaların, kozmetiklerin, çalgıların ve "ahlaksız" sayılan resim ve kitapların toplanıp yakıldığı olaya ne ad verilir?', 'Kibir Ateşi', ['Pazzi Komplosu', 'Ciompi Ayaklanması', 'Kara Ölüm Alayı'], 'İtalyancada \'Falò delle vanità\' denen bu yakma töreni Signoria Meydanı\'nda yapıldı. Savonarola ertesi yıl aynı meydanda idam edildi.'),
  ('Botticelli\'nin Uffizi\'deki 1470\'lerden kalma \'Müneccimlerin Tapınması\' tablosunu Floransa toplumu açısından özel kılan nedir?', 'Medici ailesi üyelerinin müneccimler ve maiyet olarak resmedilmesi', ['Sahnenin ilk kez gece ve mum ışığında gösterilmesi', 'Müneccimlerin Osmanlı sarayından modellerle çizilmesi', 'Tablonun papanın emriyle kentin en kalabalık kamusal meydanına konmuş olması'], 'Yaşlı müneccim Cosimo de\' Medici\'ye, diğerleri ailenin başka üyelerine benzetilmiştir. Sağ kenarda izleyiciye bakan sarı giysili figürün Botticelli\'nin kendisi olduğu kabul edilir.'),
  ('Sistina Şapeli\'nin yan duvarlarında bir yanda Musa\'nın, karşı yanda İsa\'nın yaşamından sahnelerin karşılıklı olarak yer alması hangi düşünceyi yansıtır?', 'Eski Ahit olaylarının Yeni Ahit\'i önceden haber verdiği düşüncesi', ['Musa ile İsa\'nın aynı kişi olarak kabul edilmesi', 'Yahudi ve Hristiyan cemaatlerinin eşit temsil edilmesi', 'Duvarların iki farklı papa tarafından ayrı ayrı yaptırılması'], 'Tipoloji denen bu yorumda Musa\'nın kanun koyuculuğu İsa\'nın öğretisinin öncülü sayılır. Karşılıklı sahneler, papalık otoritesini de bu süreklilik üzerine kurar.'),
  ('Mantova\'daki özel çalışma odası (studiolo) için Mantegna, Perugino ve Lorenzo Costa\'dan alegorik tablolar ısmarlayan ünlü Rönesans koleksiyoncusu kadın kimdir?', 'Isabella d\'Este', ['Lucrezia Borgia', 'Caterina Sforza', 'Vittoria Colonna'], 'Isabella d\'Este tabloların konusunu ayrıntılı sözleşmelerle belirlerdi. Leonardo\'dan da yıllarca resim istemiş, ancak yalnız bir portre çizimi alabilmiştir.'),
  ('Fresk yapımında, son ince sıva katmanı sürülmeden önce kaba alt sıvanın üzerine kırmızımsı toprak boyayla yapılan büyük boyutlu hazırlık çizimine ne ad verilir?', 'Sinopia', ['Spolvero', 'Pentimento', 'İmprimatura'], 'Adını Karadeniz kıyısındaki Sinop\'tan gelen kırmızı toprak boyadan alır. Freskler duvardan sökülüp taşındığında altlarında bu çizimler ortaya çıkmış ve ayrıca sergilenmiştir.'),
  ('Restoratörler büyük bir freskte sıvanın ek yerlerini izleyerek ressamın işi kaç günde bitirdiğini hesaplayabilir. Bu yöntemin dayandığı, her biri bir günlük çalışmayı gösteren sıva bölümlerine ne ad verilir?', 'Giornata', ['Sinopia', 'Arriccio', 'Spolvero'], 'Fresk ancak yaş sıvada kalıcı olduğundan usta her gün yalnız boyayabileceği kadar sıva sürer. Bu günlük parçaların sınırları yakından bakınca seçilebilir.'),
  ('Bir kartonun çizgileri boyunca iğneyle sık delikler açılıp üzerine kömür tozu dolu bir bez kesesiyle vurularak çizimin duvara noktalar hâlinde aktarılması yöntemine ne ad verilir?', 'Spolvero', ['Sgraffito', 'Frottage', 'Monotip'], 'Spolvero (tozlama) Rönesans fresk ve pano resminde yaygındı. Kızılötesi incelemeler birçok tablonun altında bu noktalı çizgileri göstermiştir.'),
  ('Bir ressam 30 cm genişliğindeki hazırlık çizimini kare ağla 6 m genişliğinde bir duvara büyütecektir. Çizim yatayda 10 kareye bölünmüşse duvardaki her karenin genişliği ne olmalıdır?', '60 cm', ['30 cm', '2 m', '120 cm'], 'Duvar genişliği aynı sayıda kareye bölünür: 600 cm / 10 = 60 cm. Kareleme (quadrettatura) Rönesans\'tan beri büyütme için kullanılır.'),
  ('Silinemeyen, zamanla kahverengimsi bir tona dönen ince çizgiler veren ve kâğıdın önceden kemik tozlu bir astarla hazırlanmasını gerektiren Rönesans çizim aracı hangisidir?', 'Gümüş uç', ['Grafit kalem', 'Füzen', 'Kamış kalem'], 'Gümüş uç ancak pürüzlü bir astar üzerinde iz bırakır. Leonardo, Dürer ve van Eyck bu araçla çok ince çizimler yapmıştır.'),
  ('Yağlı boya resimde beyaz astarın üzerine sürülen, resmin genel tonunu belirleyen ince ve saydam renkli ilk katmana ne ad verilir?', 'İmprimatura', ['Vernik', 'Empasto', 'Sinopia'], 'İmprimatura, parlak beyaz zemini yumuşatır ve ressama orta bir ton sağlar. Barok ressamları sık sık kırmızımsı ya da kahverengi zeminler kullanmıştır.'),
  ('Cennino Cennini\'nin anlattığı tempera geleneğinde, yüz ve ten bölgelerinin altına önce yeşil toprak boya sürülmesinin amacı nedir?', 'Üste gelen pembe tonları dengeleyerek doğal bir gölge tonu vermek', ['Boyanın panoya daha hızlı yapışmasını sağlamak', 'Figürü uzaktan bakınca solgun ve hasta göstermek', 'Altın varağın parlaklığını azaltmak'], 'Yeşil ve pembe birbirini tamamlayan renklerdir. Yeşil toprak alt katman, ten tonuna serin bir derinlik verir; eski tablolarda pembe katman aşındığında yüzler yeşilimsi görünür.'),
  ('Bir araştırmacı Flaman bir panodaki boya katmanlarının altında kalan, karbon içerikli hazırlık çizimini görmek istiyor. Hangi yöntem bu amaca en uygundur?', 'Kızılötesi reflektografi', ['Karbon-14 tarihlemesi', 'Ultraviyole floresans incelemesi', 'Dendrokronoloji'], 'Kızılötesi ışın birçok boya katmanını geçer ve karbonlu çizgilerde soğurulur. Böylece ressamın alt çizimi ve sonradan yaptığı değişiklikler görünür olur.'),
  ('Kuzey Avrupa kentlerinde ressamların bağlı olduğu loncalara, efsaneye göre Meryem\'in portresini yaptığına inanılan hangi azizin adı verilmiştir?', 'Aziz Luka', ['Aziz Markos', 'Aziz Yuhanna', 'Aziz Matta'], 'Anvers, Brugge, Delft ve Haarlem gibi kentlerde ressamlar Aziz Luka loncasına üye olmadan bağımsız atölye açamazdı.'),
  ('1563\'te Floransa\'da Vasari\'nin girişimi ve I. Cosimo de\' Medici\'nin desteğiyle kurulan, sanatçıları lonca düzeninin dışına çıkaran ilk sanat akademisi hangisidir?', 'Accademia delle Arti del Disegno', ['Accademia di San Luca', 'Accademia degli Incamminati', 'Académie royale de peinture'], 'Akademi, \'disegno\'yu resim, heykel ve mimarlığın ortak ilkesi sayıyordu. Michelangelo kurucu onur üyelerinden biri olarak gösterildi.'),
  ('Bir sunak resminin ana panosunun altında yer alan ve çoğu zaman aziz yaşamından küçük anlatı sahneleri içeren yatay şeride ne ad verilir?', 'Predella', ['Lünet', 'Pandantif', 'Frontispis'], 'Predella sahneleri ana panodaki azizlerin öykülerini ayrıntılandırır. Ressamlar burada daha serbest ve canlı anlatım denemeleri yapabilirdi.'),
  ('Büyük bir sunak resmi ısmarlanmadan önce patronun onayına sunulan, kompozisyonu ve renkleri gösteren küçük ölçekli, bitmiş görünümlü taslağa ne ad verilir?', 'Modello', ['Karton', 'Sinopia', 'Predella'], 'Modello, sözleşmenin parçası olarak patronla anlaşmayı kolaylaştırırdı. Rubens gibi büyük atölye ustaları modelloları kendileri yapar, büyük tuvali yardımcılarla tamamlardı.'),
  ('Washington\'daki Ulusal Sanat Galerisi\'nde bulunan ve Amerika kıtasındaki tek Leonardo tablosu olarak bilinen genç kadın portresi hangisidir?', 'Ginevra de\' Benci', ['Cecilia Gallerani Bergamini', 'Lisa Gherardini', 'Isabella d\'Este'], '1967\'de Lihtenştayn prens ailesinden satın alınan portre, Leonardo\'nun Floransa\'daki gençlik dönemine aittir. Cecilia Gallerani \'Kakımlı Kadın\'ın modelidir.'),
  ('Leonardo\'nun \'Ginevra de\' Benci\' portresinde genç kadının başının arkasında koyu bir ardıç çalısı yer alır. Bu bitkinin seçilmesinin bilinen nedeni nedir?', 'İtalyancadaki adı ile modelin adı arasında söz oyunu yapılması', ['Leonardo\'nun yalnız kendi bahçesindeki bitkileri çizmesi', 'Ardıcın Floransa\'da kocası ölmüş ve yas tutan kadınların geleneksel simgesi olması', 'Ardıcın Medici ailesinin hanedan arması olması'], 'Ardıç İtalyancada \'ginepro\' diye adlandırılır ve \'Ginevra\' adını çağrıştırır. Ardıç aynı zamanda iffetin de simgesi sayılırdı.'),
  ('Leonardo\'nun not defterlerindeki yazıların çoğu sağdan sola, ayna yazısıyla yazılmıştır. Bunun en yaygın kabul gören açıklaması hangisidir?', 'Solak olması ve mürekkebi elinin altında bulaştırmak istememesi', ['Kilisenin bilimsel çalışmaları yasaklaması nedeniyle gizli şifre kullanması', 'İbranice yazı geleneğini taklit etmeyi sevmesi', 'Defterlerini yalnız ayna karşısında okunacak sergi nesnesi olarak düşünmesi'], 'Leonardo soldan sağa yazmayı da biliyordu. Solak biri için sağdan sola yazmak, ıslak mürekkebin el tarafından silinmesini önler.'),
  ('Floransa\'daki Uffizi Galerisi\'nde bulunan ve Leonardo\'nun Verrocchio atölyesinde çalışırken yaptığı kabul edilen erken dönem tablosu hangisidir?', 'Müjde', ['Kayalıkların Meryemi', 'Vaftizci Yahya', 'Azize Anna ile Meryem ve Çocuk İsa'], '1470\'lerin başına tarihlenen \'Müjde\', meleğin bahçede diz çöktüğü yatay bir panodur. Seçeneklerdeki diğer tabloların tümü Louvre\'dadır.'),
  ('Leonardo\'nun 1481\'de bir manastır için başlayıp Milano\'ya gidince yarım bıraktığı, yalnız alt boyası ve hazırlık katmanıyla Uffizi\'de bulunan büyük pano hangisidir?', 'Müneccimlerin Tapınması', ['Aziz Hieronymus', 'Leda ile Kuğu', 'Kurtarıcı İsa'], 'Bu yarım eser, Leonardo\'nun kalabalık figürleri hareketli bir bütün içinde nasıl düzenlediğini gösterir. Vatikan\'daki \'Aziz Hieronymus\' da yarım kalmış bir başka Leonardo panosudur.'),
  ('Mona Lisa\'nın Fransa\'da kalarak bugün Louvre\'da bulunmasının tarihsel nedeni hangisidir?', 'Leonardo\'nun tabloyu yanında Fransa\'ya götürmesi ve tablonun kraliyet koleksiyonuna geçmesi', ['Napolyon\'un İtalya seferinde tabloyu savaş ganimeti olarak Milano\'dan alıp götürmesi', 'Medicilerin tabloyu bir evlilik çeyizi olarak Fransa\'ya göndermesi', 'Tablonun 19. yüzyılda bir açık artırmada satın alınması'], 'Leonardo son yıllarında tabloyu yanından ayırmadı. Ölümünden sonra eser I. François\'nın koleksiyonuna girdi ve devrimden sonra Louvre\'a geçti.'),
  ('Leonardo\'nun \'Son Akşam Yemeği\'nde havariler üçerli gruplar hâlinde çalkalanır, kimi geri çekilir kimi soru sorar. Ressam hangi anı resmetmiştir?', 'İsa\'nın \'İçinizden biri bana ihanet edecek\' dediği anın hemen sonrası', ['İsa\'nın ekmeği bölüp şarabı kutsadığı ayin anı', 'İsa\'nın havarilerin ayaklarını yıkadığı an', 'Yudas\'ın Getsemani bahçesinde İsa\'yı askerlere öpücükle gösterdiği an'], 'Leonardo, duyuruya verilen ani ve farklı psikolojik tepkileri göstermeyi seçmiştir. Bu yaklaşım, sakin ve sıralı önceki Son Akşam Yemeği resimlerinden ayrılır.'),
  ('Michelangelo\'nun Floransa\'daki San Lorenzo Kilisesi\'nin Yeni Sakristi\'sinde, Medici dükleri Giuliano ve Lorenzo\'nun mezarları üzerine uzanan dört alegorik figür neyi simgeler?', 'Günün dört zamanını', ['Dört mevsimi', 'Dört temel erdemi', 'Dört İncil yazarını'], 'Figürler Gece ve Gündüz ile Şafak ve Akşam olarak adlandırılır. Zamanın akışı ve ölümün kaçınılmazlığı fikrini mezar anıtına taşır.'),
  ('Michelangelo\'nun ölümünden birkaç gün öncesine dek üzerinde çalıştığı ve bugün Milano\'daki Sforza Şatosu\'nda bulunan yarım mermer Pietà hangisidir?', 'Rondanini Pietà', ['Bandini Pietà', 'Vatikan\'daki Aziz Petrus Pietà\'sı', 'Palestrina\'ya atfedilen Pietà'], 'Rondanini Pietà\'da figürler neredeyse eriyip birbirine karışmış gibidir. Ad, heykelin uzun süre bulunduğu Roma\'daki Rondanini Sarayı\'ndan gelir.'),
  ('Michelangelo\'nun kendi mezarı için düşündüğü Floransa Pietà\'sında, arkadan İsa\'nın bedenini tutan başlıklı yaşlı adam figürüne genellikle kimin yüz hatlarının verildiği kabul edilir?', 'Michelangelo\'nun kendisinin', ['Papa III. Paulus Farnese\'nin', 'Lorenzo de\' Medici\'nin', 'Giorgio Vasari\'nin'], 'Nikodemus ya da Arimatealı Yusuf olarak tanımlanan figür, sanatçının otoportresi sayılır. Michelangelo bu heykeli sonradan çekiçle kırmaya çalışmıştır.'),
  ('Papanın teşrifat sorumlusu Biagio da Cesena, \'Son Yargı\'daki çıplaklıkları eleştirince Michelangelo\'nun onu freskte nasıl resmettiği anlatılır?', 'Eşek kulaklı, beline yılan dolanmış cehennem yargıcı Minos olarak', ['Kayıkçı Kharon\'un yanında kürek çeken bir melek olarak', 'Göğe yükselen ve meleklerce taçlandırılan kutsanmış bir aziz olarak', 'İsa\'nın arkasında duran yaşlı bir peygamber olarak'], 'Vasari\'nin anlattığına göre Biagio papaya şikâyet edince papa, cehennemde yetkisi olmadığını söyleyerek şakayla karşılık verdi. Figür bugün de freskte durmaktadır.'),
  ('Michelangelo\'nun ölümünden sonra \'Son Yargı\'daki çıplak figürlerin üzerine örtüler boyadığı için \'Braghettone\' (donçu) lakabıyla anılan ressam kimdir?', 'Daniele da Volterra', ['Giorgio Vasari', 'Sebastiano del Piombo', 'Federico Zuccari'], 'Daniele, Michelangelo\'ya hayran bir ressamdı ve örtüleri olabildiğince az müdahaleyle eklemeye çalıştı. Bazı örtüler 1980-1994 restorasyonunda bile korunmuştur.'),
  ('Michelangelo\'nun Roma\'daki ilk büyük heykeli sayılan, elinde kadehle sendeleyen ve bugün Floransa\'daki Bargello Müzesi\'nde bulunan mermer eser hangisidir?', 'Bakkhus', ['Apollon', 'Herkül', 'Aziz Prokulus'], 'Heykel bir kardinal için yapılmış, beğenilmeyince banker Jacopo Galli\'ye geçmişti. Sarhoş tanrının dengesiz duruşu antik heykelleri taklit etmenin ötesine geçer.'),
  ('Genç Michelangelo\'nun \'Merdivenlerin Meryemi\' ve \'Kentaurların Savaşı\' gibi ilk kabartmalarını yaptığı, antik heykellerin toplandığı ve Bertoldo di Giovanni\'nin yönettiği öğrenme ortamı hangisidir?', 'Lorenzo de\' Medici\'nin San Marco\'daki heykel bahçesi', ['Ghiberti\'nin vaftizhane kapıları atölyesi', 'Bolonya Üniversitesi\'nin anatomi salonu', 'Vatikan\'daki Belvedere avlusunun antik heykel galerisi'], 'Lorenzo il Magnifico, yeteneğini fark ettiği genç Michelangelo\'yu evine aldı. Bu iki kabartma bugün Floransa\'daki Casa Buonarroti\'dedir.'),
  ('Sistina tavanının kenarlarında İsrail peygamberleriyle dönüşümlü olarak antik dünyanın kâhin kadınlarının (sibyllerin) yer alması hangi düşünceyi yansıtır?', 'Mesih\'in gelişinin pagan dünyada da önceden sezildiği düşüncesini', ['Antik tanrıların Hristiyanlıktan üstün olduğu inancını', 'Kadınların da kilisede rahiplik ve vaizlik yapabileceği görüşünü', 'Tavanın iki ayrı ressamca bölüşüldüğü gerçeğini'], 'Rönesans hümanizmi, pagan bilgeliği ile Hristiyan vahyini uzlaştırmaya çalışıyordu. Delfi ve Kumai sibylleri bu nedenle peygamberlerle eşit konumda gösterilmiştir.'),
  ('Michelangelo\'nun \'Son Yargı\'sının alt köşesinde, lanetlileri kayığından küreğiyle dövüp kovalayan ve Dante\'nin Cehennem\'inden esinlenilen kayıkçı figürü kimdir?', 'Kharon', ['Minos', 'Hermes', 'Kerberos'], 'Dante, Kharon\'u ateşli gözlü ve küreğiyle ruhları döven biri olarak tasvir eder. Michelangelo bu betimlemeyi neredeyse kelimesi kelimesine resme dökmüştür.'),
  ('Michelangelo\'nun ileri yaşlarında sone ve madrigaller yazdığı, dinsel çizimler armağan ettiği ve derin bir dostlukla bağlı olduğu şair kadın kimdir?', 'Vittoria Colonna', ['Veronica Franco', 'Tullia d\'Aragona', 'Gaspara Stampa da Padova'], 'Pescara markizi Vittoria Colonna, Katolik reform düşüncesine yakın bir çevrenin önemli figürüydü. Michelangelo onun ölümünden derin biçimde etkilendi.'),
  ('Vatikan\'daki Stanza della Segnatura\'da \'Atina Okulu\'nun tam karşı duvarında, felsefenin karşılığı olarak teolojiyi temsil eden Raffaello freski hangisidir?', 'Kutsal Ayin Tartışması', ['Borgo\'daki Yangın', 'Heliodoros\'un Tapınaktan Kovulması', 'Konstantin\'in Bağışı'], 'Disputa\'da yeryüzündeki kilise babaları ile gökteki azizler, sunaktaki kutsal ekmeğin çevresinde iki katlı bir düzende toplanır. Böylece akıl ile iman karşılıklı duvarlarda dengelenir.'),
  ('Raffaello\'nun Stanza della Segnatura\'daki dört büyük duvar freski bir bütün olarak hangi dört alanı temsil eder?', 'Teoloji, felsefe, şiir ve hukuk', ['Tıp, astronomi, müzik ve mimarlık', 'Dört mevsim ve dört element', 'Dört İncil yazarı ve dört kilise babası'], 'Oda büyük olasılıkla II. Julius\'un kütüphanesi olarak düzenlendi. Disputa, Atina Okulu, Parnassos ve Hukuk Erdemleri bu dört bilgi alanını simgeler.'),
  ('Raffaello\'nun Stanza d\'Eliodoro\'daki \'Aziz Petrus\'un Zindandan Kurtarılışı\' freskini Rönesans resmi içinde dikkat çekici kılan özellik hangisidir?', 'Meleğin ışığı, meşale ve ay ışığıyla kurulan bir gece sahnesi olması', ['Kalabalık bir pazar yerini gün ortasının güneşinde göstermesi', 'Figürleri altın zemin üzerinde mekânsız bırakarak Bizans geleneğine dönmesi', 'Sahneyi yalnız gri tonlarla heykel taklidi olarak boyaması'], 'Raffaello birden çok ışık kaynağını tek bir sahnede birleştirir. Meleğin parlaklığı demir parmaklıkların ardından taşar; fresk, Barok ışık oyunlarının habercisi sayılır.'),
  ('Sienalı banker Agostino Chigi\'nin Roma\'daki villası için Raffaello\'nun yaptığı, yunusların çektiği deniz kabuğu arabasında bir deniz perisini gösteren fresk hangisidir?', 'Galatea\'nın Zaferi', ['Venüs\'ün Doğuşu', 'Europa\'nın Kaçırılışı', 'Amor ile Psykhe\'nin Düğünü'], 'Fresk bugün Villa Farnesina adıyla bilinen yapıdadır. Galatea\'nın dönen bedeni, Raffaello\'nun antik güzellik idealini hareketle birleştirişini gösterir.'),
  ('Raffaello\'nun Louvre\'daki gri ve siyah tonlarda, sade ve içten portresi, saray görgüsünü anlatan \'Saray Adamı\' (Il Cortegiano) kitabının yazarını gösterir. Bu yazar kimdir?', 'Baldassare Castiglione', ['Pietro Bembo', 'Niccolò Machiavelli', 'Ludovico Ariosto'], 'Castiglione, Raffaello\'nun yakın dostuydu. Portre, daha sonra Tiziano ve Rembrandt gibi ressamlara örnek olmuştur.'),
  ('1514\'te Bramante\'nin ölümünün ardından Aziz Petrus Bazilikası\'nın baş mimarlığına getirilen ve Roma\'daki antik kalıntıları korumakla da görevlendirilen ressam kimdir?', 'Raffaello Sanzio', ['Michelangelo Buonarroti', 'Giulio Romano', 'Baldassarre Peruzzi'], 'X. Leo, Raffaello\'yu hem bazilikanın mimarı hem de antikalar sorumlusu yaptı. Raffaello, Roma\'nın antik kalıntılarının belgelenmesi için papaya bir mektup da hazırlamıştır.'),
  ('Floransa\'daki Pitti Sarayı\'nda bulunan, yuvarlak (tondo) çerçeve içinde Meryem\'in bir koltukta oturup çocuğunu sıkıca kucakladığı Raffaello tablosu hangisidir?', 'Sandalyeli Meryem', ['Saka Kuşlu Meryem', 'Çayırdaki Meryem', 'Alba Meryemi'], '\'Madonna della Seggiola\' tondonun eğrisine uyan sıkı, kucaklayıcı bir kompozisyona sahiptir. Alba Meryemi de tondo biçimlidir ama Washington\'dadır.'),
  ('Raffaello\'ya ilk resim derslerini veren babası Giovanni Santi hangi sarayda ressam ve şair olarak çalışıyordu?', 'Urbino\'daki Montefeltro sarayında', ['Mantova\'daki Gonzaga sarayında', 'Ferrara\'daki Este sarayında', 'Milano\'daki Sforza ailesinin sarayında'], 'Raffaello 1483\'te Urbino\'da doğdu. Babası çocuk yaşta ölünce Raffaello\'nun Perugino\'nun yanına gittiği kabul edilir.'),
  ('Giorgione\'nin Dresden\'deki \'Uyuyan Venüs\' tablosunun, ressamın 1510\'daki ölümünden sonra manzarası ve bazı ayrıntıları hangi ressam tarafından tamamlanmıştır?', 'Tiziano', ['Tintoretto', 'Sebastiano del Piombo', 'Palma il Vecchio'], 'Açık havada uyuyan çıplak Venüs, Tiziano\'nun sonraki \'Urbino Venüsü\'nün ve uzun bir uzanan nü geleneğinin başlangıç noktasıdır.'),
  ('Viyana\'daki Sanat Tarihi Müzesi\'nde bulunan, bir kayalık mağaranın önünde farklı yaşlarda üç adamı gösteren ve anlamı hâlâ tartışılan Giorgione tablosu hangisidir?', 'Üç Filozof', ['Fırtına', 'Konser', 'Kutsal Aile'], 'Tablodaki üç figür bilim, felsefe ya da üç dinin temsilcileri gibi çeşitli biçimlerde yorumlanmıştır. Belirsizlik Giorgione\'nin şiirsel üslubunun bir parçasıdır.'),
  ('Roma\'daki Borghese Galerisi\'nde bulunan, bir lahit biçimli çeşmenin iki yanında biri giyinik biri çıplak iki kadını gösteren erken Tiziano tablosu hangisidir?', 'Kutsal ve Dünyevi Aşk', ['Diana ile Kallisto', 'Venüs ile Adonis\'in Vedalaşması', 'Flora'], 'Tablo bir Venedikli devlet adamının düğünü için yapılmıştı. İki kadın, Rönesans Yeni Platonculuğunun iki Venüs kavramıyla yorumlanır.'),
  ('Ferrara Dükü Alfonso d\'Este\'nin özel odası için yapılan, bir tanrının leoparların çektiği arabasından terk edilmiş bir prensese doğru sıçradığı anı gösteren Tiziano tablosu hangisidir?', 'Bakkhus ve Ariadne', ['Diana ve Aktaion', 'Venüs ve Adonis', 'Perseus ve Andromeda'], 'Tablo bugün Londra\'daki Ulusal Galeri\'dedir. Parlak ultramarin gökyüzü ve canlı hareket, Tiziano\'nun renkçi üslubunun ilk büyük örneklerindendir.'),
  ('Tiziano\'nun Venedik\'teki Frari Kilisesi\'nde bulunan \'Pesaro Ailesinin Meryemi\' sunak resminde getirdiği kompozisyon yeniliği hangisidir?', 'Meryem\'i ortadan sağa kaydırıp köşegen, asimetrik bir düzen kurması', ['Bağışçı aileyi resmin dışında bırakıp yalnız azizleri göstermesi', 'Meryem\'i tahtın tam ortasına koyarak iki yanına azizleri eşit sayıda dizdiği kusursuz bir simetri kurması', 'Sahneyi altın zemin üzerinde mekânsız olarak boyaması'], 'Geleneksel sunak resimlerinde Meryem merkezdedir. Tiziano\'nun kaydırılmış ekseni ve büyük sütunları, Barok kompozisyonların habercisi sayılır.'),
  ('Tiziano\'nun geç dönem tablolarında boyayı yakından bakınca dağınık görünen lekelerle, anlatılana göre zaman zaman parmaklarıyla sürdüğü görülür. Bu yaklaşım sonraki dönemde en çok kimleri etkilemiştir?', 'Velázquez ve Rembrandt gibi Barok ustalarını', ['Floransalı maniyerist çizgi ustalarını ve onların akademik izleyicilerini', 'Erken Flaman minyatür ressamlarını', 'Bizans ikona ressamlarını'], 'Uzaktan bakınca bütünleşen serbest fırça işi, 17. yüzyılda ressamca (pictorial) üslubun temeli oldu. Velázquez, Tiziano\'yu İspanyol kraliyet koleksiyonunda inceleme olanağı bulmuştu.'),
  ('Tintoretto\'nun San Giorgio Maggiore Kilisesi\'ndeki \'Son Akşam Yemeği\'ni Leonardo\'nun aynı konudaki freskinden ayıran temel düzen farkı hangisidir?', 'Masanın derinliğe doğru çapraz uzanması ve dumanlı ışıkta meleklerin belirmesi', ['Masanın resim düzlemine paralel yerleştirilip havarilerin tek sıra dizilmesi', 'İsa\'nın masada hiç gösterilmeyip yalnız havarilerin resmedilmesi', 'Sahnenin açık havada, gün ışığında bir bahçede ve kalabalık bir şölen olarak geçmesi'], 'Tintoretto statik simetri yerine köşegen hareket ve tek bir kandilin yarattığı dramatik ışık kullanır. Bu, maniyerizmden Barok\'a geçişin özelliklerini taşır.'),
  ('Kaynakların anlattığına göre Tintoretto atölyesinin duvarına hangi ilkeyi yazmıştır?', 'Michelangelo\'nun çizgisi, Tiziano\'nun rengi', ['Doğa tek öğretmendir, ustalar değil', 'Önce ışık, sonra biçim', 'Raffaello\'nun zarafeti, Leonardo\'nun gölgesi'], '17. yüzyıl yazarı Carlo Ridolfi\'nin aktardığı bu ilke, Floransa\'nın disegno\'su ile Venedik\'in colorito\'sunu birleştirme hedefini anlatır.'),
  ('Tintoretto\'nun \'Kölenin Mucizesi\' tablosunda, işkence görmek üzere yere yatırılmış köleyi kurtarmak için gökten baş aşağı süzülerek inen aziz kimdir?', 'Aziz Markos', ['Aziz Yorgi', 'Aziz Nikolaos', 'Aziz Sebastianus'], 'Tablo Scuola Grande di San Marco için yapılmıştır. Venedik\'in koruyucu azizi Markos, keskin kısaltımla havadan dalarken gösterilir.'),
  ('Venedik Doçlar Sarayı\'nın Büyük Konsey Salonu\'nu kaplayan ve dünyanın en büyük tuval resimlerinden biri sayılan Tintoretto eseri hangisidir?', 'Cennet', ['Son Yargı', 'Kana\'daki Düğün', 'Venedik\'in Zaferi'], '\'Il Paradiso\' yirmi metreyi aşan genişliğiyle yüzlerce figür içerir. Tintoretto bu dev işi oğlu Domenico ve atölyesiyle tamamlamıştır.'),
  ('Palladio\'nun Maser\'deki Villa Barbaro\'sunda, yarı açık kapılardan bakan uşaklar ve balkonlardan sarkan aile üyeleri gibi göz yanılsamalı freskler yapan ressam kimdir?', 'Paolo Veronese', ['Jacopo Tintoretto', 'Giovanni Battista Tiepolo', 'Andrea Mantegna'], 'Veronese\'nin freskleri, villanın gerçek mimarisiyle boyalı mimariyi birbirine karıştırır. Bu iş, Rönesans villa dekorasyonunun en ünlü örneklerindendir.'),
  ('Correggio\'nun \'Jüpiter ve İo\' tablosunda baş tanrı Jüpiter, kollarını açmış genç İo\'yu hangi biçimde sarmalar?', 'Gri, yoğun bir bulut olarak', ['Altın bir yağmur olarak', 'Beyaz bir kuğu olarak', 'Kanatlı bir kartal olarak'], 'Tablo, Correggio\'nun Mantova Dükü için yaptığı \'Jüpiter\'in Aşkları\' dizisindendir. Bulutun içinde yüzün ve elin seçilmesi duyusal bir etki yaratır.'),
  ('Pontormo\'nun Floransa\'daki Santa Felicita Kilisesi\'nde bulunan \'Çarmıhtan İndiriliş\' tablosunu maniyerizmin tipik örneği yapan özellik hangisidir?', 'Haçsız, zemini belirsiz bir boşlukta yüzer gibi duran figürler ve keskin pastel renkler', ['Tek kaçış noktasına göre kurulmuş derin bir manzara, sakin gökyüzü ve doğal gün ışığı', 'Karanlık zeminden sert bir ışıkla aydınlanan sokak tipleri', 'Figürlerin sakin bir piramit içinde dengeli biçimde toplanması'], 'Pontormo haçı ve sahnenin mekânını neredeyse yok eder. Yerçekimsiz figürler ve pembe, açık mavi gibi yapay renkler, Yüksek Rönesans dengesinden bilinçli bir uzaklaşmadır.'),
  ('Volterra\'daki köşeli, keskin hatlı figürlerle dolu \'Çarmıhtan İndiriliş\' tablosunu yapan ve sonra Fransa\'ya giderek I. François\'nın sarayında çalışan Floransalı maniyerist kimdir?', 'Rosso Fiorentino', ['Jacopo Pontormo', 'Agnolo Bronzino', 'Domenico Beccafumi'], 'Rosso, 1530\'da Fontainebleau\'ya gitti ve orada ölümüne dek kraliyet galerisi üzerinde çalıştı. Volterra\'daki tablosu çarpıcı ve sinirli bir enerji taşır.'),
  ('I. François\'nın Fontainebleau Sarayı\'ndaki galeriyi alçı kabartma ve fresklerle süsleyerek \'Fontainebleau Okulu\'nu başlatan iki İtalyan sanatçı kimlerdir?', 'Rosso Fiorentino ve Francesco Primaticcio', ['Leonardo da Vinci ve Francesco Melzi', 'Benvenuto Cellini ve Giambologna', 'Andrea del Sarto ile öğrencisi Jacopo Carucci Pontormo'], 'Galerie François I\'de boyalı panolar, onları çevreleyen yüksek alçı figür ve kartuşlarla birleşir. Bu birleşim Kuzey Avrupa süsleme sanatını derinden etkiledi.'),
  ('Bronzino\'nun Uffizi\'deki portresi, I. Cosimo de\' Medici\'nin eşini küçük oğluyla, nar desenli görkemli bir brokar elbise içinde gösterir. Bu kadın kimdir?', 'Toledolu Eleonora', ['Caterina de\' Medici', 'Bianca Cappello', 'Lucrezia Tornabuoni'], 'İspanyol bir soylu aileden gelen Eleonora, Medici sarayında güçlü bir figürdü. Bronzino\'nun soğuk, kusursuz yüzeyi giysinin dokusunu neredeyse elle tutulur kılar.'),
  ('Parmigianino\'nun Viyana\'daki otoportresinde ön plandaki el, yüze göre olağandışı büyük görünür. Bunun nedeni nedir?', 'Dışbükey bir aynadaki yansımayı yarım küre biçimli bir tahtaya aktarması', ['Ressamın bilerek elini büyüterek sol elini sakladığını göstermesi', 'Tablonun sonradan kesilip yeniden çerçevelenmesi', 'Ressamın gerçekte bir el hastalığı nedeniyle eli şişmiş olduğu için onu olduğu gibi çizmesi'], 'Parmigianino, bir berberin dışbükey aynasında gördüğü görüntüyü aynı eğrilikte bir yüzeye resmetti. Aynaya en yakın el büyür, oda kenarlarda bükülür.'),
  ('Mantova\'daki Palazzo Te\'de, duvarları ve tavanı kesintisiz kaplayarak Olimpos\'tan atılan yıldırımlarla devlerin üzerine çöken kayaları gösteren fresk odasını kim yapmıştır?', 'Giulio Romano', ['Andrea Mantegna', 'Correggio', 'Primaticcio'], 'Raffaello\'nun baş yardımcısı olan Giulio Romano, Sala dei Giganti\'de izleyiciyi felaketin ortasına yerleştiren bir yanılsama kurdu. Oda maniyerizmin oyunbaz ve şaşırtıcı yanını gösterir.'),
  ('Maniyerist kuramcı Lomazzo\'nun övdüğü, gövdenin alevi andıran S biçimli bir dönüşle burulduğu figür duruşuna ne ad verilir?', 'Figura serpentinata', ['Kontrapost', 'Sfumato', 'Di sotto in sù'], '\'Yılansı figür\' anlamına gelen kavram, kontrapostun abartılı ve sarmal bir biçimidir. Michelangelo\'nun bir sözüne dayanılarak açıklandığı anlatılır.'),
  ('Giambologna\'nın, tek ayak ucuyla bir rüzgâr tanrısının ağzından çıkan soluğun üzerinde duruyormuş gibi gösterilen ünlü bronz heykeli hangisidir?', 'Uçan Merkür', ['Perseus ve Medusa', 'Herkül ve Kentaur Nessos', 'Neptün Çeşmesi'], 'Heykel neredeyse ağırlıksız bir hız etkisi yaratır. Pek çok kopyası yapılan eserin özgün dökümlerinden biri Floransa\'daki Bargello\'dadır.'),
  ('Kavgaları, hapisten kaçışları ve Perseus heykelinin dramatik dökümünü canlı bir dille anlatan otobiyografisiyle edebiyat tarihine de giren Rönesans sanatçısı kimdir?', 'Benvenuto Cellini', ['Giorgio Vasari', 'Baccio Bandinelli', 'Leon Battista Alberti'], 'Cellini\'nin \'Yaşam\'ı (Vita) yüzyıllar sonra yayımlandı ve dönemin sanatçı yaşamına dair en canlı tanıklıklardan biri oldu.'),
  ('Giuseppe Arcimboldo\'nun meyve, sebze ve çiçeklerden oluşan \'Vertumnus\' adlı bileşik portresi hangi Habsburg imparatorunu gösterir?', 'II. Rudolf', ['V. Karl', 'I. Ferdinand', 'II. Maximilian'], 'Vertumnus, mevsimlerin Roma tanrısıdır. İmparatoru bolluk tanrısı olarak göstermek, saray içinde hem şaka hem de övgü işlevi görüyordu.'),
  ('Maniyerizm adı İtalyanca \'maniera\' sözcüğünden gelir. Vasari bu sözcüğü olumlu anlamda kullanırken neyi kastetmiştir?', 'Ustaca kazanılmış zarif ve kendine özgü bir üslubu', ['Doğayı hiçbir yorum ya da seçim katmadan olduğu gibi kopyalamayı', 'Kaba ve özensiz bir çalışma biçimini', 'Yalnız dinsel konuları işleyen bir resim türünü'], 'Vasari\'de \'bella maniera\', büyük ustaların incelemesiyle olgunlaşmış güzel üslup demekti. Kavram, sonraki yüzyıllarda yapaylık anlamıyla olumsuzlaştı.'),
  ('Vasari\'nin \'hatasız ressam\' diye andığı, Pontormo ve Rosso Fiorentino\'nun da hocası olan ve \'Harpiyalı Meryem\' sunağıyla tanınan Floransalı ressam kimdir?', 'Andrea del Sarto', ['Fra Bartolomeo', 'Ridolfo Ghirlandaio', 'Mariotto Albertinelli'], 'Andrea del Sarto Yüksek Rönesans\'ın kusursuz tekniğini temsil eder. Öğrencileri ise bu dengeyi bozan yeni bir üsluba yöneldi.'),
  ('Jan van Eyck\'in \'Şansölye Rolin\'in Meryemi\' tablosunda bağışçı Nicolas Rolin, Meryem\'le aynı odada ve aynı ölçekte diz çökmüş hâlde gösterilir. Bu düzen neyi vurgular?', 'Bağışçının toplumsal gücünü ve Tanrı\'ya doğrudan yakınlık iddiasını', ['Rolin\'in aslında sanatçının akrabası olduğunu ve onun atölyesinde yardımcı olarak çalıştığını', 'Meryem\'in sıradan bir burjuva kadını olarak görüldüğünü', 'Tablonun bir mahkeme kararıyla kiliseye bağışlandığını'], 'Önceki sunaklarda bağışçılar genellikle küçük ve kenarda gösterilirdi. Burgonya dükünün güçlü şansölyesi, kutsal figürle eşit bir mekânı paylaşır.'),
  ('Londra\'daki Ulusal Galeri\'de bulunan, çerçevesinde \'Als ich can\' yazısı da yer aldığı için çoğu araştırmacının Jan van Eyck\'in otoportresi saydığı 1433 tarihli tablo hangisidir?', 'Kırmızı Türbanlı Adam', ['Arnolfini Portresi', 'Timotheos', 'Margaret van Eyck\'in Portresi'], 'Kırmızı başlığın karmaşık kıvrımları ve izleyiciye doğrudan bakan gözler, otoportre olasılığını güçlendirir. Ressam karısı Margaret\'in portresini de yapmıştır.'),
  ('Rogier van der Weyden\'in, ressamların koruyucu azizini Meryem\'in ve Çocuk İsa\'nın portresini çizerken gösterdiği tablosu hangisidir?', 'Aziz Luka Meryem\'i Çizerken', ['Aziz Hieronymus Çalışma Odasında', 'Aziz Eligius Atölyesinde', 'Aziz Yuhanna Patmos\'ta'], 'Boston\'da bulunan bu tablo, van Eyck\'in Rolin Meryemi\'nin düzenine benzer. Bazı araştırmacılar Luka\'nın yüzünde ressamın kendi portresini görür.'),
  ('Rogier van der Weyden 1436\'dan itibaren hangi kentin resmî kent ressamı olarak çalışmıştır?', 'Brüksel', ['Brugge', 'Anvers', 'Ghent'], 'Kent ressamı olarak belediye binası için adalet konulu büyük tablolar yaptı; bunlar 1695 bombardımanında yok oldu.'),
  ('Petrus Christus\'un 1449 tarihli tablosu, dükkânında yüzük tartan bir kuyumcuyu genç bir çiftle gösterir. Bu tablo Flaman resminde hangi türün öncülerinden sayılır?', 'Gündelik yaşam sahnesi', ['Tarih resmi', 'Hayvan resmi', 'Kent manzarası'], 'Dinsel bir figür yerine bir zanaatkârın dükkânı merkezdedir; yine de kuyumcunun Aziz Eligius olabileceği tartışılır. Tablo, sonraki tür resminin habercisi sayılır.'),
  ('Quentin Matsys\'in \'Tefeci ve Karısı\' tablosunda kadın, dua kitabının sayfasını çevirirken gözünü kocasının tarttığı paralara diker. Bu ayrıntı neyi anlatır?', 'Dünyevi zenginliğin dinsel görevi gölgelemesini', ['Kadının muhasebeyi yöneten asıl kişi olduğunu', 'Çiftin okuma yazma bilmediğini', 'Paranın kilise bağışı için sayıldığını ve tefecinin tövbe ettiğini'], 'Kitap ile terazi karşıtlığı ahlaki bir uyarı taşır. Masadaki dışbükey ayna da dış dünyayı odaya katarak van Eyck geleneğine gönderme yapar.'),
  ('Hieronymus Bosch\'un \'Saman Arabası\' triptiğinde insanların merdivenlerle tırmanıp kapışmaya çalıştığı dev saman yığını neyi simgeler?', 'Geçici dünyevi mallara duyulan açgözlülüğü', ['Köylülerin soylulara karşı ayaklanmasını', 'Bereketli hasat için Tanrı\'ya duyulan şükranı ve köy toplumunun dayanışmasını', 'Kilisenin yoksullara yaptığı yardımı'], 'Flaman atasözüne göre dünya bir saman yığınıdır; herkes ondan kapabildiğini kapar. Araba sonunda sağ kanattaki cehenneme doğru ilerler.'),
  ('Prado\'daki, Bosch\'a atfedilen \'Yedi Ölümcül Günah\' masa panosunda günah sahneleri, ortasında \'Dikkat, dikkat, Tanrı görüyor\' yazan dev bir dairenin çevresine dizilir. Bu daire neyi simgeler?', 'Her şeyi gören Tanrı\'nın gözünü', ['Dünyanın dönen çarkını', 'Kıyamet gününün güneşini', 'Bir saat kadranının akıp giden zamanı'], 'Göz bebeğinin içinde mezarından kalkan İsa görülür. İzleyici, günahları seyrederken kendisinin de izlendiğini hatırlar.'),
  ('Bosch\'un \'Dünyevi Zevkler Bahçesi\' triptiğinin kanatları kapatıldığında dış yüzde ne görülür?', 'Saydam bir küre içinde yeni yaratılmakta olan dünya', ['Bağışçı ailenin dua eden portreleri', 'Cehennemde yanan ve iblislerce cezalandırılan günahkârların kalabalığı', 'Altın zemin üzerinde Meryem ve melekler'], 'Dış kanatlar gri tonlarla (grisaille) boyanmıştır. Tanrı sol üst köşede küçük bir figür olarak yaratılışın üçüncü gününü seyreder.'),
  ('Bruegel\'in \'Körlerin Benzetmesi\' tablosunda altı kör adam köşegen bir çizgi boyunca sırayla tökezleyip düşer. Tablo hangi İncil sözünü görselleştirir?', 'Kör köre kılavuzluk ederse ikisi de çukura düşer', ['Göğün egemenliği yoksullarındır', 'Gözünüzdeki merteği görmez, kardeşinizin gözündeki çöpü görürsünüz', 'İğne deliğinden deve geçer'], 'Kompozisyonun soldan sağa inen çizgisi, düşüşün kaçınılmazlığını adım adım gösterir. Eser Napoli\'deki Capodimonte Müzesi\'ndedir.'),
  ('Karel van Mander\'e göre Pieter Bruegel\'in köylü düğünlerine ve şenliklerine kılık değiştirerek katılıp onları gözlemlemesi, ressama hangi lakabı kazandırmıştır?', 'Köylü Bruegel', ['Cehennem Bruegel', 'Kadife Bruegel', 'Çiçek Bruegel'], '\'Boeren-Bruegel\' lakabı, onun köylü yaşamını içeriden gözlemleyen bakışını anlatır. Ressamın kendisi ise Anvers ve Brüksel\'in kültürlü çevrelerine mensuptu.'),
  ('Pieter Bruegel\'in küçük oğlu olan, ince işlenmiş çiçek natürmortları ve Rubens\'le birlikte yaptığı tablolarla tanınan, \'Kadife Brueghel\' lakaplı ressam kimdir?', 'Jan Brueghel (Yaşlı)', ['Pieter Brueghel (Genç)', 'Ambrosius Brueghel', 'Jan Brueghel (Genç)'], 'Lakap, yumuşak ve parlak boya yüzeyinden ya da kadife giysilerinden gelir. Ağabeyi Pieter (Genç) ise babasının eserlerini kopyalamasıyla tanınır.'),
  ('Albrecht Dürer\'in 1498\'de kendi yayımladığı ve \'Mahşerin Dört Atlısı\' sahnesini de içeren büyük boyutlu ağaç baskı dizisi hangisidir?', 'Kıyamet (Apokalips)', ['Büyük Tutku (Çarmıh Öyküsü)', 'Meryem\'in Yaşamı', 'Küçük Tutku'], 'Yuhanna\'nın Vahiy kitabını işleyen dizi, 1500 yılı yaklaşırken yayılan kıyamet beklentisiyle büyük ilgi gördü. Dürer\'i genç yaşta Avrupa çapında tanınır kıldı.'),
  ('Dürer\'in \'Şövalye, Ölüm ve Şeytan\' gravüründe zırhlı şövalye, elinde kum saati tutan Ölüm\'e ve arkasındaki şeytana aldırmadan yoluna devam eder. Bu sahne genellikle neyi simgeler?', 'İnancıyla tehlikelere kayıtsız kalan Hristiyan erdemini', ['Haçlı seferlerinin yenilgiyle sonuçlanmasını', 'Şövalyelik çağının ölümünü ve yerini paralı askerlere bırakmasını', 'Ressamın kendi hastalığını ve ölüm korkusunu'], 'Erasmus\'un \'Hristiyan Askerin El Kitabı\'ndaki imana dayalı kararlılık ideali sık sık bu gravürle ilişkilendirilir. Şövalyenin dimdik profili, çevresindeki dehşetle karşıtlık oluşturur.'),
  ('Dürer\'in çok tanınan \'Dua Eden Eller\' çizimi aslında neyin hazırlık çalışması olarak yapılmıştır?', 'Bir sunak resmindeki havari figürünün elleri', ['Ressamın annesinin ölüm döşeği portresi', 'Bir dua kitabının kapak süslemesi', 'Nürnberg kilisesi için bir mezar taşı kabartması'], 'Çizim, Frankfurtlu tüccar Jakob Heller için yapılan sunak resmine hazırlıktı. Sunak sonradan yangında yok oldu; çizim ise bağımsız bir simgeye dönüştü.'),
  ('Dürer\'in 1526\'da Nürnberg kent meclisine armağan ettiği, altındaki yazıtlarda Luther\'in İncil çevirisinden alıntılar bulunan iki panoluk eseri hangisidir?', 'Dört Havari', ['Adem ile Havva', 'Paumgartner Sunağı', 'Heller Sunağı'], 'Nürnberg o yıl Lutherciliği benimsemişti. Yazıtlar, sahte peygamberlere karşı uyarılarla kentin yeni inancına bir tür vasiyet niteliği taşır.'),
  ('Dürer\'in, bir ressamın ızgaralı bir çerçeve ve sabit bir göz noktası aracılığıyla uzanan bir kadını çizdiğini gösteren gravürü hangi konuyu öğretmek için yapılmıştır?', 'Perspektifli çizimin mekanik yöntemini', ['Çıplak model çalışmasının ahlaki sakıncalarını', 'Gölgelendirmede çapraz tarama tekniğini', 'Yağlı boya için tuval germe işlemini'], 'Gravür, Dürer\'in \'Ölçme Üzerine Kılavuz\' kitabının 1538 baskısında yer alır. Izgara, görüntünün kare kare kâğıda aktarılmasını sağlar.'),
  ('Hans Holbein\'in, ölümün papadan imparatora, tüccardan köylüye herkesi alıp götürdüğünü gösteren küçük boyutlu ağaç baskı dizisi hangisidir?', 'Ölüm Dansı', ['Yedi Ölümcül Günah', 'Ölümün Zaferi', 'Kıyamet Atlıları'], 'Dizi 1538\'de Lyon\'da kitap olarak yayımlandı. Ortaçağ \'danse macabre\' geleneğini keskin bir toplumsal eleştiriyle birleştirir.'),
  ('Dostoyevski\'nin \'Budala\' romanında bir karakterin \'bu resme bakan kişi inancını yitirebilir\' dediği, mezarda yatan İsa\'yı çürüme belirtileriyle gösteren uzun ve dar tablo kimindir?', 'Hans Holbein (Genç)', ['Matthias Grünewald', 'Lucas Cranach (Yaşlı)', 'Albrecht Altdorfer'], '\'Mezardaki Ölü İsa\' Basel\'dedir. Dostoyevski tabloyu orada görmüş ve derinden sarsılmıştır.'),
  ('VIII. Henry\'nin, Holbein\'in yaptığı portresini görüp evlenmeye karar verdiği, ama yüz yüze görünce hayal kırıklığına uğradığı anlatılan dördüncü eşi kimdir?', 'Klevesli Anne', ['Jane Seymour', 'Anne Boleyn', 'Catherine Howard'], 'Evlilik altı ay sürmeden bozuldu. Portre bugün Louvre\'dadır ve Holbein\'in diplomatik portrecilikteki rolünü gösterir.'),
  ('Albrecht Altdorfer ve Wolf Huber gibi ressamların ormanlık dağ manzaralarını duygusal bir anlatımla işlediği ve bağımsız manzara resminin erken örneklerini veren akıma ne ad verilir?', 'Tuna Okulu', ['Köln Okulu', 'Fontainebleau Okulu', 'Haarlem Okulu'], 'Bu ressamlar Alpler ve Tuna boyunun ormanlarını sık dallar ve dramatik ışıkla resmetti. Altdorfer\'in figürsüz manzaraları Batı resminde öncü sayılır.'),
  ('Grünewald\'ın Isenheim Sunağı\'ndaki İsa\'nın yaralarla kaplı, yeşilimsi bedeni, sunağın bulunduğu kurumdaki izleyicilere özellikle neden anlamlı gelmiştir?', 'Sunağın, deri yaraları yapan bir salgına yakalananlara bakan bir hastanede olması', ['Sunağın idam mahkûmlarının son gecelerini geçirdiği bir zindanda bulunması', 'Sunağın Haçlı seferlerinden dönen askerler için yapılmış olması', 'Sunağın deri tabaklayan ustaların loncasına ait küçük bir şapelde asılı olması'], 'Antonitler, çavdar mahmuzu zehirlenmesinin yol açtığı \'Aziz Antonius ateşi\' hastalarına bakıyordu. Hastalar kendi acılarını çarmıhtaki İsa\'nın acısında görebiliyordu.'),
  ('Raffaello\'nun kompozisyonlarını bakır gravürlerle çoğaltarak onları Avrupa\'nın dört bir yanındaki sanatçılara tanıtan Bolonyalı gravürcü kimdir?', 'Marcantonio Raimondi', ['Ugo da Carpi', 'Agostino Veneziano', 'Giorgio Ghisi da Mantova'], 'Raimondi ile Raffaello arasındaki iş birliği, baskıyı resim kompozisyonlarını yayan bir araç hâline getirdi. Manet\'nin yararlandığı Paris\'in Yargısı gravürü de ona aittir.'),
  ('Rönesans ve Barok resimlerinde yanında dikenli, kırık bir tekerlek bulunan prenses giysili azize kimdir?', 'İskenderiyeli Azize Katerina', ['Azize Barbara', 'Azize Cecilia', 'Azize Agnes'], 'Efsaneye göre Katerina\'yı işkence için bağladıkları çivili tekerlek mucizevi biçimde parçalanmıştır. Barbara kuleyle, Cecilia org ya da müzik aletleriyle, Agnes kuzuyla tanınır.'),
  ('Elinde bir tabak, tabağın içinde bir çift göz taşıyan azize hangisidir?', 'Azize Lucia', ['Azize Agatha', 'Azize Apollonia', 'Azize Margareta'], 'Lucia\'nın adı Latince ışık (lux) sözcüğünü çağrıştırır ve gözlerin koruyucusu sayılır. Agatha ise tabakta kesilmiş göğüslerle gösterilir.'),
  ('Yanında bir demir ızgarayla resmedilen ve efsaneye göre bu ızgara üzerinde diri diri yakılarak şehit edilen Romalı diyakoz kimdir?', 'Aziz Laurentius', ['Aziz Stefanos', 'Aziz Vincentius', 'Aziz Bartholomeus'], 'Laurentius 258\'de Roma\'da şehit edildi. Stefanos ise taşlanarak öldürüldüğü için başında ya da elinde taşlarla gösterilir.'),
  ('Dört İncil yazarının geleneksel simgelerinde (tetramorf) kanatlı öküz hangisini temsil eder?', 'Luka', ['Matta', 'Markos', 'Yuhanna'], 'Matta insan ya da melekle, Markos aslanla, Luka öküzle, Yuhanna kartalla simgelenir. Öküz, Luka İncili\'nin kurban temasıyla ilişkilendirilir.'),
  ('Rönesans resimlerinde çoğunlukla elinde bir kılıç ve kitapla, kel başlı ve uzun sakallı gösterilen havari kimdir?', 'Aziz Pavlus', ['Aziz Petrus', 'Aziz Andreas', 'Aziz Yakup'], 'Kılıç, Pavlus\'un Roma yurttaşı olduğu için başının kılıçla kesilerek öldürülmesine işaret eder. Kitap ise yazdığı mektupları simgeler.'),
  ('Bir sunak panosunda haç görünmüyor; İsa\'nın ölü bedeni yere serilmiş bir örtünün üzerinde yatıyor, çevresinde Meryem, Yuhanna ve Mecdelli Meryem yas tutuyor. Bu sahne hangi konudur?', 'Ölü İsa\'ya Ağıt', ['Çarmıhtan İndiriliş', 'Dirilişten Sonra Görünme', 'Göğe Yükseliş'], 'Ağıt (Lamentation) sahnesi indirilişten sonra, gömülmeden önceki yası gösterir. İndiriliş ise bedenin haçtan aşağı alınma anıdır; Giotto ve Mantegna konuyu farklı yorumlamıştır.'),
  ('Meryem\'in melekler ve azizler arasında tahtta görkemle oturduğu, özellikle Duccio ve Giotto\'nun büyük sunaklarıyla tanınan resim türünün İtalyanca adı nedir?', 'Maestà', ['Pietà', 'Annunziata', 'Deesis'], '\'Haşmet\' anlamına gelen Maestà, Meryem\'in Gökler Kraliçesi olarak yüceltilmesini anlatır. Duccio\'nun Siena Katedrali için yaptığı Maestà, kentte törenle taşınmıştır.'),
  ('Leonardo ve Michelangelo\'nun bugün yalnız kopyalardan bilinen kayıp eserlerinin konusu olan, Zeus\'un kuğu kılığında yaklaştığı Spartalı kraliçe kimdir?', 'Leda', ['Danae', 'Europa', 'Semele'], 'Leonardo\'nun Leda\'sı ayakta, Michelangelo\'nunki uzanmış biçimde tasarlanmıştı. İki eser de yok olmuş, kopyalar ve çizimlerle bilinir.'),
  ('Kartal kılığına giren Zeus\'un kaçırarak Olimpos\'ta tanrıların sakisi yaptığı Truvalı genç kimdir?', 'Ganymedes', ['Adonis', 'Narkissos', 'Endymion'], 'Michelangelo\'nun Tommaso de\' Cavalieri\'ye armağan ettiği bir çizim de bu konuyu işler. Konu Rönesans Yeni Platonculuğunda ruhun tanrısal olana yükselişi olarak da yorumlandı.'),
  ('Botticelli\'nin \'Venüs ve Mars\' tablosunda Mars zırhını çıkarmış, derin uykudadır; Venüs ise uyanık ve dingin biçimde onu izler. Bu düzen hangi düşünceyi anlatır?', 'Aşkın savaşı yatıştırıp yendiğini', ['Savaşın aşktan daha güçlü olduğunu', 'Tanrıların insanlara kayıtsız kaldığını', 'Evliliğin özgürlüğü sınırladığını'], 'Mars\'ın mızrağıyla oynayan küçük satirler de savaşçının silahsız kaldığını vurgular. Tablo bir evlilik armağanı olarak yapılmış olabilir.'),
  ('Roma\'daki Santa Maria del Popolo Kilisesi\'nin Cerasi Şapeli\'nde bulunan, attan düşmüş bir adamın kollarını açarak sırtüstü yattığı ve atın resim alanının büyük kısmını kapladığı Caravaggio tablosu hangisidir?', 'Saul\'un Dönüşümü', ['Aziz Matta\'nın Çağrılışı', 'Aziz Yorgi ve Ejderha', 'Aziz Martinus ile Dilenci'], 'Şam yolunda Tanrı\'nın sesini duyup yere düşen Saul, sonradan Pavlus adını alır. Caravaggio mucizeyi göksel figürler olmadan, yalnız ışıkla anlatır.'),
  ('Caravaggio\'nun Londra\'daki \'Emmaus\'ta Akşam Yemeği\' tablosunda, meyve sepeti masanın kenarından taşacakmış gibi durur ve bir havarinin kolu izleyiciye doğru uzanır. Bu düzen hangi etkiyi amaçlar?', 'Resim alanını izleyicinin bulunduğu mekâna doğru taşırmayı', ['Masadaki nesneleri ayrı bir natürmort gibi sahneden koparmayı', 'İzleyiciyi sahneden uzak bir tanık konumunda tutmayı', 'Sahneye ölçülü, durağan bir Rönesans dengesi kazandırmayı'], 'Yanılsamacı ayrıntılar, izleyiciyi tanıma anının içine çeker. İsa\'nın sakalsız gösterilmesi de havarilerin onu neden hemen tanımadığını düşündürür.'),
  ('Caravaggio\'nun Toskana Grandükü için dışbükey bir tören kalkanı üzerine boyadığı, saçları yılanlarla dolu, çığlık atan kesik baş hangi mitolojik figürdür?', 'Medusa', ['Gorgo Stheno', 'Hydra', 'Erinys'], 'Kalkan bugün Uffizi\'dedir. Dışbükey yüzeye rağmen baş, yüzeyden fırlıyormuş gibi bir yanılsamayla boyanmıştır.'),
  ('Caravaggio\'nun bugün Louvre\'da bulunan \'Meryem\'in Ölümü\' tablosu, ısmarlayan Roma kilisesince geri çevrilmiştir. Bunun temel nedeni nedir?', 'Meryem\'in şiş karınlı ve çıplak ayaklı sıradan bir ölü gibi gösterilmesi', ['Tablonun sözleşmede istenenden çok küçük boyutta yapılması', 'Meryem\'in göğe yükselirken meleklerle gösterilmesi', 'Ressamın tabloyu teslim etmeden önce başka bir alıcıya satması'], 'Kutsal figüre yakışır görülmeyen bu gerçekçilik tepki çekti. Tabloyu Mantova Dükü\'nün satın almasını, o sırada İtalya\'da bulunan genç Rubens önermiştir.'),
  ('Malta\'daki Valletta Katedrali\'nde bulunan ve Caravaggio\'nun imzasını kurbanın boynundan akan kanın içine yazdığı, imzalı tek tablosu hangisidir?', 'Vaftizci Yahya\'nın Başının Kesilmesi', ['Aziz Hieronymus Yazarken', 'Azize Ursula\'nın Şehitliği', 'Lazarus\'un Dirilişi'], 'Caravaggio Malta\'da tarikata şövalye olarak kabul edilmiş, kısa süre sonra tutuklanıp kaçmıştı. Kocaman tablo bu kısa dönemin başyapıtıdır.'),
  ('Caravaggio\'nun ayna karşısında kendini yeşilimsi bir tenle, elinde üzüm salkımı tutan bir şarap tanrısı olarak resmettiği erken dönem tablosu hangisidir?', 'Hasta Bakkhus', ['Kertenkele Isırmış Oğlan', 'Meyve Sepetli Oğlan', 'Narkissos'], 'Tablo Roma\'daki ilk yıllarında, ressamın hastalıktan yeni çıktığı döneme tarihlenir. Model bulamadığı için kendini resmettiği düşünülür.'),
  ('Annibale Carracci\'nin, kaba bir masada kâseden çorba ve fasulye yerken kaşığı ağzına götüren ve izleyiciye bakan bir köylüyü gösteren tablosu hangisidir?', 'Fasulye Yiyen Adam', ['Kasap Dükkânı', 'Patates Yiyenler', 'Köylü Yemeği'], 'Tablo bugün Roma\'daki Colonna Galerisi\'ndedir. Hızlı fırça ve gündelik konu, Carracci\'nin idealleştirilmiş tavan resimleri yanında doğrudan gözleme verdiği önemi gösterir.'),
  ('Roma\'daki Barberini Sarayı\'nın büyük salonunun tavanında, Barberini ailesinin arması olan dev arıların göğe taşındığı \'İlahi Takdirin Zaferi\' freskini yapan ressam kimdir?', 'Pietro da Cortona', ['Andrea Sacchi', 'Giovanni Lanfranco', 'Guido Reni'], 'Fresk, Barberini ailesinden Papa VIII. Urbanus\'u yüceltir. Kalabalık ve hareketli kompozisyonu, Barok tavan resminin en etkili örneklerindendir.'),
  ('Çok hızlı ve çok üretken çalışmasıyla \'Luca fa presto\' (Luca çabuk yapar) lakabını alan, İspanya\'da Escorial\'in tavanlarını da boyayan Napolili Barok ressam kimdir?', 'Luca Giordano', ['Luca Cambiaso', 'Mattia Preti', 'Francesco Solimena'], 'Giordano binlerce eser bırakmıştır. Lakabın, babasının onu daha hızlı çalışması için sürekli uyarmasından geldiği anlatılır.'),
  ('Vahşi dağ manzaraları, kırık ağaçlar ve haydut figürleriyle tanınan, 18. yüzyılda \'yüce\' (sublime) duygusunun öncüsü sayılan Napolili Barok ressam kimdir?', 'Salvator Rosa', ['Claude Lorrain', 'Gaspard Dughet', 'Domenico Zampieri'], 'Rosa\'nın ürkütücü doğası, Claude\'un dingin ve altın ışıklı manzaralarının tam karşıtıdır. İngiliz Romantikleri onun eserlerine büyük ilgi göstermiştir.'),
  ('Artemisia Gentileschi\'nin 1610\'da on yedi yaşındayken yaptığı ve bilinen ilk imzalı tablosu sayılan eser hangi konuyu işler?', 'Susanna ve İhtiyarlar', ['Yudit ve Holofernes', 'Lukretia\'nın Ölümü', 'Kleopatra\'nın Ölümü'], 'Tabloda iki yaşlı adamın gizlice gözetlediği genç kadının rahatsızlığı güçlü biçimde verilir. Konu Barok resminde çok yaygındı, ama Artemisia onu kadının bakış açısından ele alır.'),
  ('Artemisia Gentileschi\'nin kendini öne eğilmiş, fırçası elinde, boynunda maske biçimli bir kolyeyle resim sanatının kişileştirmesi olarak gösterdiği tablosu hangisidir?', 'Resim Alegorisi Olarak Otoportre', ['Lavtalı Otoportre', 'Azize Katerina Olarak Otoportre', 'Şehit Olarak Otoportre'], 'Bu eser bugün İngiliz Kraliyet Koleksiyonu\'ndadır. Erkek ressamlar resim alegorisini bir kadın figürüyle gösterebilirken, Artemisia aynı anda hem sanatçı hem alegori olabilmişti.'),
  ('Aziz Petrus Bazilikası\'nın apsisinde, havarinin ahşap tahtına inanılan kalıntıyı dev bir bronz kılıf içinde dört kilise babasının taşıdığı ve üstünde sarı alabastır bir pencerede güvercin bulunan Bernini eseri hangisidir?', 'Petrus\'un Kürsüsü (Cathedra Petri)', ['Baldaken (Baldacchino)', 'Longinus Heykeli', 'VIII. Urbanus\'un Mezarı'], 'Güvercin Kutsal Ruh\'u simgeler; pencereden giren gerçek ışık altın ışınlarla birleşir. Eser papalığın Petrus\'tan gelen otoritesini görkemli bir sahneye dönüştürür.'),
  ('Bernini\'nin Cornaro Şapeli\'nde Azize Teresa grubunun iki yanındaki duvarlarda, tiyatro locaları içinde sohbet eden Cornaro ailesi üyelerinin heykelleri yer alır. Bu düzen esere nasıl bir boyut katar?', 'Mucizeyi bir sahne gibi izleyen seyirciler ekleyerek izleyiciyi de bu seyre katar', ['Aileyi mucizenin asıl kahramanı yaparak Teresa\'yı ikinci plana iter', 'Şapeli bir aile mezarlığından çok bir mahkeme salonuna dönüştürür', 'Heykelleri ışıktan koruyarak boyalarını uzun süre saklar'], 'Bernini, mimariyi, heykeli ve ışığı bir tiyatro düzeni içinde birleştirmiştir. Locadaki figürler bizim gibi tanıklardır; bazıları tartışır, bazıları başka yöne bakar.'),
  ('Bernini\'nin \'Azize Teresa\'nın Vecdi\' heykel grubuna yukarıdan düşen ve onu bir görü gibi aydınlatan ışık nereden gelir?', 'Alınlığın arkasına gizlenmiş sarı camlı bir pencereden', ['Şapelin tabanına yerleştirilmiş yağ kandillerinden', 'Mermerin içine oyulmuş fosforlu boyalardan', 'Karşı duvardaki geniş vitraydan yansıyan güneşten'], 'Görünmeyen pencereden gelen ışık, arkadaki yaldızlı bronz ışınlarla birleşir. İzleyici kaynağı göremediği için ışık doğaüstü bir nitelik kazanır.'),
  ('Bernini\'nin sevgilisi Costanza Bonarelli\'nin mermer büstünü dönemin portre büstlerinden ayıran temel özellik hangisidir?', 'Resmî bir kişiyi değil, sıradan bir kadını samimi ve anlık bir ifadeyle göstermesi', ['Kadını antik bir tanrıça kılığında, ideal ve soğuk bir güzellikle göstermesi', 'Büstün altın varak ve renkli taşlarla boyanmış olması', 'Yüzün ölümünden sonra alınmış bir maskeden kopyalanması'], 'Aralık dudaklar, açık yaka ve dağınık saçlar, heykelin bir kamusal anıt değil özel bir anı olduğunu gösterir. Büst Floransa\'daki Bargello\'dadır.'),
  ('Bernini, Kardinal Scipione Borghese\'nin mermer büstünü bitirdikten kısa süre sonra aynı büstü baştan ikinci kez yapmıştır. Bunun nedeni nedir?', 'İlk büstün alnında mermerde bir çatlak ortaya çıkması', ['Kardinalin ilk büstteki yüz ifadesini beğenmemesi', 'İlk büstün papaya armağan edilmesi', 'Büstün taşınırken yere düşüp kırılması'], 'Bernini ikinci büstü birkaç günde tamamladığı anlatılır. İki büst bugün Borghese Galerisi\'nde yan yana durur.'),
  ('Roma\'daki Santa Maria sopra Minerva meydanında, sırtında küçük bir Mısır dikilitaşı taşıyan mermer fil heykelinin tasarımı kime aittir?', 'Gian Lorenzo Bernini', ['Francesco Borromini', 'Carlo Maderno', 'Alessandro Algardi'], 'Romalıların \'Pulcino della Minerva\' dediği anıt 1667\'de dikildi. Fil, bilgeliği taşımak için güçlü bir aklın gerektiğini simgeler.'),
  ('Bernini\'nin Kardinal Scipione Borghese için yaptığı ilk büyük heykel grubunda, Truva\'dan kaçan Aeneas sırtında yaşlı babasını taşır. Bu baba figürü kimdir?', 'Ankhises', ['Priamos', 'Laokoon', 'Nestor'], 'Grup, Bernini\'nin babası Pietro ile birlikte yaptığı düşünülen erken bir eserdir. Üç kuşağı üst üste sarmal biçimde yerleştiren düzen, sonraki gruplarının habercisidir.'),
  ('Yüz hatlarını abartarak gülünç bir benzerlik yakalayan portre çizimlerini, yani karikatür türünü ilk kez bir sanat oyunu olarak geliştirdiği kabul edilen Bolonyalı ressamlar kimlerdir?', 'Carracci kardeşler', ['Bellini kardeşler', 'Van Eyck kardeşler', 'Le Nain kardeşler'], 'İtalyanca \'caricare\' (yüklemek, abartmak) sözcüğünden gelen \'ritratti carichi\' Carracci atölyesinde ortaya çıktı. Bernini de sonradan ünlü karikatür çizimleri yapmıştır.'),
  ('Velázquez\'in ön planda yün eğiren işçi kadınları, arka planda ise Athena ile dokumacı Arakhne\'nin yarışını gösteren katmanlı tablosu hangisidir?', 'İplikçi Kadınlar', ['Bakkhus\'un Zaferi', 'Vulcanus\'un Demirhanesi', 'Mars\'ın Dinlenmesi'], '\'Las Hilanderas\' adlı tablo, gündelik emek ile mitolojiyi aynı mekânda birleştirir. Arka plandaki halı, Tiziano\'nun \'Europa\'nın Kaçırılışı\'nı taklit eder.'),
  ('1914\'te Londra\'daki Ulusal Galeri\'de bir süfrajet tarafından bıçakla yaralanan ve Velázquez\'in günümüze ulaşan tek kadın çıplağı olan tablo hangisidir?', 'Aynadaki Venüs (Rokeby Venüsü)', ['Uyuyan Venüs (Dresden Venüsü)', 'Urbino Venüsü', 'Venüs ve Adonis'], 'Mary Richardson tabloya saldırarak kadınlara oy hakkı mücadelesine dikkat çekmek istedi. Tablo onarılmış, kesikler bugün yakından bakılınca seçilebilir.'),
  ('Velázquez\'in Sevilla döneminde yaptığı, mutfak eşyaları ve yiyeceklerle birlikte halktan insanları gösteren \'Yumurta Kızartan Yaşlı Kadın\' gibi tablolara İspanyolcada hangi ad verilir?', 'Bodegón', ['Vanitas', 'Capriccio', 'Veduta'], 'Bodegón sözcüğü meyhane ya da aşevi anlamındaki \'bodega\'dan gelir. Velázquez bu türde nesnelerin dokusunu ve ışığını olağanüstü bir gerçeklikle vermiştir.'),
  ('Velázquez\'in şarap tanrısını İspanyol köylüleriyle birlikte içerken gösterdiği, halk arasında \'Sarhoşlar\' (Los Borrachos) diye anılan tablosu hangisidir?', 'Bakkhus\'un Zaferi', ['Bakkhus ve Ariadne', 'Tanrıların Şöleni', 'Kana\'daki Düğün'], 'Tablo, mitolojiyi kaba saba gerçek yüzlerle karıştırır. Tanrının ışıklı bedeni ile köylülerin güneşten yanmış yüzleri arasındaki karşıtlık dikkat çeker.'),
  ('Velázquez\'in 1650\'de Roma\'da portresini yaptığı, aynı yıl azat belgesini imzaladığı ve sonradan kendisi de ressam olan Endülüslü yardımcısı kimdir?', 'Juan de Pareja', ['Juan Bautista Martínez del Mazo', 'Alonso Cano', 'Juan Carreño de Miranda'], 'Portre Roma\'da sergilendiğinde büyük beğeni topladı. Pareja, Velázquez\'in ölümünden sonra kendi dinsel tablolarını imzalayan bir ressam oldu.'),
  ('Velázquez\'in Sevilla\'daki hocası ve kayınpederi olan, \'Resim Sanatı\' (Arte de la pintura) adlı kuramsal kitabı yazan ressam kimdir?', 'Francisco Pacheco', ['Francisco de Herrera', 'Juan de Roelas', 'Antonio Palomino'], 'Pacheco, öğrencisinin yeteneğini erken fark edip onu kızıyla evlendirdi. Kitabı, İspanyol resminin ikonografi kuralları için önemli bir kaynaktır.'),
  ('Velázquez\'in IV. Felipe\'nin sarayındaki cüceleri ve soytarıları gösteren portreleri sanat tarihçilerince genellikle nasıl değerlendirilir?', 'Onları alay nesnesi değil, kendi onuru olan bireyler olarak gösterdiği', ['Sarayın eğlence kültürünü küçümseyen keskin karikatürler olduğu', 'Bilimsel bir tıp kitabı için yapılmış anatomi çizimleri olduğu', 'Ressamın kendi hayal gücünden uydurduğu alegorik tipler olduğu'], 'Velázquez bu figürlere soylularınkine benzer bir ciddiyet ve iç dünya tanır. Örneğin Sebastián de Morra\'nın keskin bakışı izleyiciyi doğrudan sorgular.'),
  ('İspanyol Barok ahşap heykellerinde cam gözler, fildişi dişler, gerçek saç ve kumaş giysiler kullanılmasının başlıca amacı nedir?', 'Dinsel alaylarda izleyiciyi sarsacak canlı bir gerçeklik yaratmak', ['Heykellerin ağırlığını azaltarak kolay taşınmalarını sağlamak', 'Pahalı mermer bulunamadığı için ucuz bir çözüm üretmek', 'Eserlerin antik Roma heykellerine benzemesini sağlamak'], 'Karşı Reform sanatı inananı duygusal olarak etkilemeyi hedefliyordu. Kutsal Hafta alaylarında taşınan bu heykeller, izleyiciyi İsa\'nın ve Meryem\'in acısına ortak eder.'),
  ('New York\'taki Metropolitan Müzesi\'nde bulunan, yeşilimsi fırtınalı bir gök altında tepe üzerine kurulmuş bir İspanyol kentini gösteren El Greco tablosu hangisidir?', 'Toledo Manzarası', ['Madrid Görünümü', 'Sevilla\'nın Kuşbakışı', 'Escorial\'e Fırtına Düşerken'], 'Tablo, Batı resminde bir kenti bağımsız konu olarak işleyen erken manzaralardandır. El Greco kentin yapılarını gerçek konumlarından bilerek oynatmıştır.'),
  ('Londra\'daki Banqueting House\'un tavanına Rubens\'in yaptığı büyük tuval resimleri hangi İngiliz kralını yüceltir?', 'I. James', ['I. Charles', 'II. Charles', 'VIII. Henry'], 'Tavan, I. Charles tarafından babası I. James\'in bilge yönetimini kutlamak için ısmarlandı. I. Charles 1649\'da bu yapının önünde kurulan iskelede idam edildi.'),
  ('Rubens\'in 53 yaşındayken evlendiği, \'Küçük Kürk\' adlı tablosunda yalnız bir kürk pelerine sarınmış olarak gösterdiği on altı yaşındaki ikinci eşi kimdir?', 'Helena Fourment', ['Isabella Brant', 'Susanna Lunden', 'Hélène Bruegel'], 'Rubens bu tabloyu satmamış, vasiyetinde doğrudan eşine bırakmıştır. Helena, Rubens\'in son dönem tablolarında sık sık model olarak görülür.'),
  ('Rubens\'in kendisini ilk eşiyle birlikte bir hanımeli çardağının altında el ele oturur gösterdiği evlilik portresindeki eşinin adı nedir?', 'Isabella Brant', ['Helena Fourment', 'Margaretha van Eyck', 'Saskia van Uylenburgh'], 'Portre 1609\'daki evliliklerinin hemen ardından yapıldı. Isabella 1626\'da veba salgınında öldü; Saskia ise Rembrandt\'ın eşidir.'),
  ('Rubens\'in Floransa\'daki \'Savaşın Sonuçları\' tablosunda kollarını göğe kaldırmış, siyah giysili, yas tutan kadın neyi temsil eder?', 'Otuz Yıl Savaşları\'nın yıktığı Avrupa\'yı', ['Savaşı kazanan İspanya Krallığı\'nı', 'Rubens\'in ölen ilk eşini', 'Barışı getiren Meryem\'i'], 'Rubens bir mektubunda bu figürü yıllardır yağmalanan ve acı çeken Avrupa olarak açıklamıştır. Mars, Venüs\'ün kollarından kurtulup yıkıma koşar.'),
  ('Van Dyck\'in I. Charles\'ı taç ve zırh yerine av giysisi içinde, atı ve seyisiyle birlikte rahat ama kendinden emin bir duruşla gösterdiği portre bugün hangi müzededir?', 'Louvre Müzesi\'nde', ['Londra\'daki Ulusal Galeri\'de', 'Prado Müzesi\'nde', 'Ermitaj Müzesi\'nde'], '\'Avdaki I. Charles\' resmî bir taç portresi olmadan kralın doğal soyluluğunu vurgular. 18. yüzyılda Fransız kraliyet koleksiyonuna girmiştir.'),
  ('Van Dyck\'in I. Charles\'ı aynı tuvalde cepheden, yandan ve dörtte üç açıdan gösterdiği portre hangi amaçla yapılmıştır?', 'Bernini\'nin Roma\'da kralın mermer büstünü yapabilmesi için', ['Kralın paralara basılacak profilini seçmek için', 'Kraliçeye üç farklı ruh hâlini göstermek için', 'Bir anatomi kitabında kafa yapısını incelemek için'], 'Bernini kralı hiç görmemişti; büstü bu portreden yola çıkarak yaptı. Büst 1698\'de Whitehall Sarayı yangınında yok oldu.'),
  ('Van Dyck\'in İtalya\'da kaldığı yıllarda soylu aileler için en çok portre yaptığı ve uzun boylu, zarif aristokrat imajını geliştirdiği liman kenti hangisidir?', 'Cenova', ['Napoli', 'Venedik', 'Livorno'], 'Marchesa Elena Grimaldi\'nin portresi bu dönemin ünlü örneğidir. Cenova\'daki zengin bankacı aileleri ressamın başlıca müşterileriydi.'),
  ('Arşidük Leopold Wilhelm\'in Brüksel\'deki resim galerisini, duvarları yüzlerce küçük tablo kopyasıyla dolu biçimde birçok kez resmeden saray ressamı kimdir?', 'David Teniers (Genç)', ['Frans Francken (Genç)', 'Jan Brueghel (Yaşlı)', 'Willem van Haecht'], 'Teniers ayrıca koleksiyonun gravürlü bir kataloğunu hazırladı. Bu resimler, bugün Viyana\'daki Sanat Tarihi Müzesi\'nin çekirdeğini oluşturan koleksiyonun belgeleridir.'),
  ('Rembrandt\'ın 1662 tarihli grup portresinde, Amsterdam kumaş loncasının denetçileri bir masanın çevresinde oturur ve sanki biri odaya yeni girmiş gibi başlarını kaldırıp izleyiciye bakar. Bu tablo hangisidir?', 'Kumaşçılar Loncası Denetçileri', ['Dr. Deyman\'ın Anatomi Dersi', 'Okçular Loncasının Şöleni', 'Huzurevi Yöneticileri'], '\'Staalmeesters\' adıyla da bilinen tablo, izleyiciyi sahnenin bir parçası yapan anlık bakışlarla grup portresine canlılık kazandırır. Rijksmuseum\'dadır.'),
  ('Van Gogh\'un bir mektubunda \'önünde iki hafta kuru ekmekle oturabilmek için ömrümden on yıl verirdim\' dediği Rembrandt tablosu hangisidir?', 'Yahudi Gelin', ['Müsrif Oğulun Dönüşü', 'Gece Devriyesi', 'Kumaşçılar Loncası Denetçileri'], 'Van Gogh tabloyu 1885\'te yeni açılan Rijksmuseum\'da gördü. Erkeğin elini kadının göğsüne koyduğu şefkatli jest ve kalın boya katmanları onu derinden etkilemişti.'),
  ('Rembrandt\'ın \'Banyodaki Bathşeba\' tablosunun modeli olduğu düşünülen, Saskia\'nın ölümünden sonra ressamla nikâhsız yaşadığı için kilise konseyince sorguya çekilen kadın kimdir?', 'Hendrickje Stoffels', ['Geertje Dircx', 'Titia van Uylenburgh', 'Cornelia van Rijn'], 'Hendrickje, Rembrandt\'la kızı Cornelia\'yı dünyaya getirdi. Saskia\'nın vasiyetindeki koşul yüzünden Rembrandt yeniden evlenmek istememişti.'),
  ('Rembrandt\'ın birçok kez resmettiği, Saskia\'dan doğan ve 1668\'de babasından bir yıl önce ölen oğlunun adı nedir?', 'Titus', ['Cornelis', 'Willem', 'Jacob'], 'Titus, iflasın ardından Hendrickje ile birlikte Rembrandt\'ın eserlerini satan bir şirket kurarak babasını korudu. Ölümü Rembrandt\'ın son yılını derinden sarstı.'),
  ('Rembrandt\'ın öğrencisi olan, \'Saka Kuşu\' tablosuyla tanınan ve 1654\'te Delft\'teki barut deposu patlamasında ölen ressam kimdir?', 'Carel Fabritius', ['Ferdinand Bol', 'Govert Flinck', 'Nicolaes Maes'], 'Patlama kentin büyük bölümünü yıktı ve Fabritius\'un eserlerinin çoğu yok oldu. Lahey\'deki Mauritshuis\'te bulunan \'Saka Kuşu\' bir roman ile tanınırlığını artırmıştır.'),
  ('Donmuş kanallarda paten kayan kalabalıkları gösteren kış manzaralarıyla tanınan ve sağır-dilsiz olduğu için \'Kampen\'in Dilsizi\' lakabıyla anılan Hollandalı ressam kimdir?', 'Hendrick Avercamp', ['Aert van der Neer', 'Esaias van de Velde', 'Jan van Goyen'], 'Avercamp\'ın sahneleri, \'Küçük Buz Çağı\' denen soğuk dönemin gündelik yaşamını belgeler. Her sınıftan insanı buz üzerinde bir arada gösterir.'),
  ('Kalvinist dönemde beyaza boyanmış, süssüz kilise iç mekânlarını titiz perspektif ölçümleriyle ve açık, sakin tonlarla resmeden Haarlemli ressam kimdir?', 'Pieter Saenredam', ['Emanuel de Witte', 'Gerard Houckgeest', 'Hendrick van Vliet'], 'Saenredam yapıları önce yerinde ölçüp çizdi, tabloyu yıllar sonra bu çizimlerden yaptı. Kiliselerin boş ve aydınlık görünümü Protestan ibadet anlayışını yansıtır.'),
  ('1566\'da Hollanda\'da Kalvinist kalabalıkların kiliselerdeki heykel ve resimleri parçaladığı ikonoklazma olaylarına Hollandacada ne ad verilir?', 'Beeldenstorm', ['Alteratie', 'Rampjaar', 'Tulpenmanie'], '\'İmge fırtınası\' anlamına gelen olaylar, Hollanda\'da dinsel sanat siparişini büyük ölçüde sona erdirdi. Ressamlar sonraki yüzyılda portre, manzara ve natürmort gibi türlere yöneldi.'),
  ('Delft\'te tuğla avluları ve açık kapılardan ardışık arka odalara uzanan aydınlık iç mekânlarıyla tanınan, Vermeer\'in çağdaşı ressam kimdir?', 'Pieter de Hooch', ['Nicolaes Maes', 'Emanuel de Witte', 'Gabriel Metsu'], 'De Hooch, ev içi düzeni ve kadınların gündelik işlerini sakin bir geometriyle gösterir. Vermeer\'in iç mekân anlayışıyla karşılıklı etkileşim içindedir.'),
  ('1699\'da kızıyla birlikte Güney Amerika\'daki Surinam\'a giderek böceklerin başkalaşımını gözlemleyen ve gözlemlerini 1705\'te ayrıntılı resimli bir kitapta yayımlayan sanatçı ve doğa bilimci kimdir?', 'Maria Sibylla Merian', ['Rachel Ruysch', 'Anna Maria van Schurman', 'Margaretha de Heer'], 'Merian, tırtıldan kelebeğe dönüşümü besin bitkileriyle birlikte gösterdi. Eseri bilim ile sanatın birleştiği önemli bir yayın sayılır.'),
  ('Marcel Proust\'un romanında yazar Bergotte\'un, eserdeki \'küçük sarı duvar parçası\'na hayranlıkla bakarken öldüğü Vermeer tablosu hangisidir?', 'Delft Manzarası', ['Küçük Sokak', 'Süt Döken Kadın', 'Resim Sanatı'], 'Proust tabloyu dünyanın en güzel resmi saymıştı. Lahey\'deki Mauritshuis\'te bulunan eser, nehir kıyısından görülen kentin sabah ışığını gösterir.'),
  ('Vermeer\'in sırtı izleyiciye dönük bir ressamın, Klio kılığına girmiş bir modeli resmettiği ve II. Dünya Savaşı\'nda Hitler\'in koleksiyonuna geçen tablosu hangisidir?', 'Resim Sanatı', ['Gökbilimci', 'Coğrafyacı', 'Konser'], 'Viyana\'daki Sanat Tarihi Müzesi\'nde bulunan tablo, arka duvardaki büyük Hollanda haritasıyla da tanınır. Vermeer bu eseri ölümüne dek satmamıştır.'),
  ('Georges de La Tour\'un Louvre\'daki tablosunda, kart oyunu oynayan saf bir genç dolandırılırken bir kadın ve hizmetçisi yan bakışlarla işaretleşir, bir adam da kemerinin arkasından bir kart çıkarır. Bu tablo hangisidir?', 'Karo Asıyla Hileci', ['Kâhin Kadın', 'Kart Oynayanlar', 'Zar Atan Askerler'], 'La Tour gündüz sahnelerinde sert ışık ve gizli bakışlarla bir ahlak öyküsü kurar. Konu Caravaggio\'nun \'Kumarbaz Hileciler\'ini hatırlatır.'),
  ('Fransız köylü ailelerini yoksulluk içinde ama ağırbaşlı, durgun ve törensel bir sessizlikle gösteren tablolarıyla tanınan üç ressam kardeş hangi soyadını taşır?', 'Le Nain', ['Le Brun', 'Le Sueur', 'Le Moyne'], 'Antoine, Louis ve Mathieu Le Nain\'in tablolarını birbirinden ayırmak hâlâ güçtür. Köylülere tanıdıkları saygınlık, dönemin saray zevkinden ayrılır.'),
  ('1701\'de altmış üç yaşındaki XIV. Louis\'yi ermin kürklü taç giyme kaftanı içinde, eli asasına dayalı ayakta gösteren ve sonraki saray portrelerine örnek olan tablonun ressamı kimdir?', 'Hyacinthe Rigaud', ['Nicolas de Largillière', 'Philippe de Champaigne', 'Jean-Marc Nattier'], 'Portre başlangıçta İspanya kralı olan torunu için yapıldı; kral beğenip Versailles\'da tuttu. Kralın balet ayakları ve görkemli kumaşlar dikkat çeker.'),
  ('17. yüzyıl sonunda Fransız Akademisi\'nde resmin temelinin çizgi mi renk mi olduğu tartışılmıştır. Rengin üstünlüğünü savunan tarafa hangi ad verilmiştir?', 'Rubensçiler (Rubénistes)', ['Poussinciler (Poussinistes)', 'Caravaggistler', 'Akademisyenler'], 'Çizgiyi savunanlar Poussin\'i, rengi savunanlar Rubens\'i örnek gösterdi. Tartışmayı sonunda renkçilerin önde geldiği Roger de Piles kazandı ve bu, Rokoko\'nun yolunu açtı.'),
  ('Watteau\'nun Paris\'teki sanat tüccarı Gersaint\'in dükkânı için yaptığı tabelada, eski kral XIV. Louis\'nin portresinin bir sandığa yerleştirilmesi nasıl yorumlanır?', 'Bir çağın kapanıp yeni ve hafif bir zevkin başlaması olarak', ['Kralın sanat tüccarlarına borçlu öldüğünün kanıtı olarak', 'Gersaint\'in yalnızca kraliyet portreleri sattığının ilanı olarak', 'Ressamın saraydan sürgün edilmesine duyduğu öfke olarak'], 'Tablo 1720\'de, XIV. Louis\'nin ölümünden birkaç yıl sonra yapıldı. Ağır saray sanatının paketlenip yerini zarif koleksiyoncu zevkine bıraktığı düşüncesini taşır.'),
  ('Watteau\'nun figür çizimlerinde kırmızı, siyah ve beyaz tebeşiri tonlu bir kâğıt üzerinde birlikte kullanma tekniğine ne ad verilir?', 'Üç kalem (trois crayons)', ['Gümüş uç (silverpoint)', 'Mürekkep yıkama (lavis)', 'Kömür kalem (füzen)'], 'Üç rengin birleşimi tenin sıcaklığını ve gölgelerini hızlıca vermeye yarar. Rubens\'ten de etkilenen Watteau bu tekniği zarif bir ustalıkla kullandı.'),
  ('1720\'de Paris\'te pastel portreleriyle büyük ilgi gören, Fransız Kraliyet Akademisi\'ne üye seçilen ve pastel modasını yayan Venedikli kadın sanatçı kimdir?', 'Rosalba Carriera', ['Angelica Kauffman', 'Élisabeth Vigée Le Brun', 'Giulia Lama'], 'Carriera tabakalar üzerine minyatür portrelerle başlamış, sonra pastelin yumuşak ve tozlu yüzeyini portrede ustaca kullanmıştır. Avrupa\'nın birçok sarayından sipariş aldı.'),
  ('Canaletto\'nun keskin çizgili ve aydınlık kent görünümlerinden farklı olarak Venedik\'i titrek fırça vuruşları, puslu ışık ve küçük hareketli figürlerle resmeden ressam kimdir?', 'Francesco Guardi', ['Bernardo Bellotto', 'Michele Marieschi', 'Luca Carlevarijs'], 'Guardi\'nin Venedik\'i belgesel olmaktan çok atmosferik ve şiirseldir. Bu serbest anlatım 19. yüzyılda yeniden değer kazandı.'),
  ('Gerçek ve hayalî yapıların, yıkıntıların ve manzaraların düşsel biçimde bir araya getirildiği 18. yüzyıl manzara türüne İtalyanca ne ad verilir?', 'Capriccio', ['Veduta', 'Bambocciata', 'Quadratura'], 'Capriccio \'heves, kapris\' anlamına gelir. Canaletto, Guardi ve Piranesi bu türde gerçek mimariyi hayal gücüyle yeniden düzenledi.'),
  ('Canaletto, 1746\'da Venedik\'ten ayrılıp yaklaşık on yıl başka bir ülkede çalışmıştır. Bu ülkeyi seçmesinin başlıca nedeni nedir?', 'Asıl müşterileri olan İngiliz gezginlerin savaş yüzünden Venedik\'e gelememesi', ['Venedik\'te resim yapmanın yasalarla yasaklanması', 'Avusturya imparatorunun onu saray ressamı olarak zorla çağırması', 'Venedik\'teki büyük yangında atölyesinin yok olması'], 'Avusturya Veraset Savaşı Büyük Tur yolculuklarını azalttı. Canaletto bu yüzden İngiltere\'ye gidip Thames ve Londra manzaraları yaptı.'),
  ('Trento Konsili\'nin 1563\'te dinsel imgeler üzerine aldığı karar, sanatçılardan genel olarak ne bekliyordu?', 'Resimlerin açık, anlaşılır ve inananı dindarlığa yönelten nitelikte olmasını', ['Kiliselerde hiçbir figürlü resim bulunmamasını', 'Yalnızca soyut geometrik süslemeler kullanılmasını', 'Konuların tümüyle sanatçının kişisel hayal gücüne ve zevkine bırakılmasını'], 'Protestan eleştirilere karşı Katolik Kilisesi imgelerin öğretici gücünü savundu, ama karışık, yanlış ya da uygunsuz betimlemeleri yasakladı. Bu tutum Barok dinsel sanatın zeminini hazırladı.'),
  ('Heinrich Wölfflin\'in kavramlarına göre Barok resmin \'açık biçim\'i hangi özellikle tanınır?', 'Hareketin ve figürlerin çerçevenin dışına taşıyormuş gibi görünmesi', ['Kompozisyonun çerçeve içinde kendine dönük, simetrik biçimde kapanması', 'Figürlerin keskin konturlarla birbirinden ayrılması', 'Bütün ögelerin resim düzlemine paralel dizilmesi'], 'Açık biçimde köşegenler ve kesilmiş figürler, sahnenin çerçeve dışında sürdüğü izlenimini verir. Rönesans\'ın kapalı biçimi ise kendi içinde tamamlanmış bir düzen kurar.'),
  ('Leonardo\'nun ışık-gölge geçişleri ile Caravaggio\'nun tenebrizmi karşılaştırıldığında temel fark nedir?', 'Caravaggio\'da karanlık baskındır ve ışıktan gölgeye geçiş serttir', ['Caravaggio gölgeleri hiç kullanmayıp düz renkler sürer', 'Leonardo\'da sahneler hep gece ve tek bir mum ışığı altında geçer', 'Leonardo\'da ışık tek bir sert projektör gibi düşer'], 'Leonardo yumuşak, dumanlı geçişlerle hacim kurar. Caravaggio ise koyu zeminden sert bir ışıkla seçilen figürlerle dramatik bir karşıtlık yaratır.'),
  ('15. yüzyılda Erken Hollanda ressamları ile aynı dönemin Floransalı ressamları karşılaştırıldığında hangi ayrım genel olarak doğrudur?', 'Floransalılar geometri ve anatomiye, Hollandalılar yüzey ayrıntısına ve ışığın dokulardaki etkisine yöneldi', ['Hollandalılar perspektifi Floransalılardan önce matematiksel kurallarla kitaplaştırdı', 'Floransalılar yalnız yağlı boya, Hollandalılar yalnız fresk kullandı', 'Her iki gelenek de dinsel konuları tümüyle bırakıp portreye yöneldi'], 'Masaccio ve Piero mekânı ölçülü geometrik bir düzenle kurarken van Eyck kumaşın, metalin ve camın ışığı nasıl yansıttığını ayrıntıyla gösterdi. İki yaklaşım yüzyılın sonunda birbirini etkiledi.'),
  ('Aşağıdaki heykellerden hangisi en erken tamamlanmıştır?', 'Ghiberti\'nin Vaftizhane kuzey kapıları', ['Michelangelo\'nun Vatikan\'daki Pietà heykeli', 'Cellini\'nin Perseus\'u', 'Bernini\'nin Apollon ve Daphne\'si'], 'Kuzey kapıları 1424\'te, Pietà 1499\'da, Perseus 1554\'te, Apollon ve Daphne 1625\'te tamamlandı.'),
  ('Michelangelo Sistina Şapeli tavanını 1512\'de bitirmiş, aynı şapelin sunak duvarındaki \'Son Yargı\'ya 1536\'da başlamıştır. İki iş arasında kaç yıl geçmiştir?', '24', ['14', '29', '19'], '1536 - 1512 = 24. Bu sürede Roma 1527\'de yağmalanmış ve Reform tartışmaları başlamıştı; Son Yargı\'nın karanlık havası bu değişimi yansıtır.'),
  ('Bir Orta Çağ sunak resminde Meryem yanındaki bağışçılardan birkaç kat büyük gösterilir; bir Rönesans sunağında ise bağışçılar Meryem\'le hemen hemen aynı boydadır. Bu fark neyi gösterir?', 'Figür boyunun önem yerine mekândaki uzaklığa göre belirlenmeye başlamasını', ['Orta Çağ ressamlarının oran bilgisinin hiç olmamasını', 'Rönesans\'ta bağışçıların artık Meryem\'den daha önemli ve kutsal sayılmasını', 'Rönesans\'ta dinsel figürlerin resimden çıkarılmasını'], 'Hiyerarşik ölçekte boyut kutsallığı ve önemi gösterir. Doğrusal perspektifin yerleşmesiyle boyut, figürün izleyiciye uzaklığına bağlanır.'),
  ('Gabriel Metsu\'nun bir tablosunda mektup okuyan kadının hizmetçisi, duvardaki tablonun perdesini aralar; perdenin altında fırtınalı bir deniz manzarası görünür. Bu deniz resmi neye işaret eder?', 'Mektuptaki aşk ilişkisinin çalkantılı ve tehlikeli olduğuna', ['Kadının kocasının uzak bir denizde gemi kazasında öldüğüne', 'Evin bir gemi kaptanına ait olduğuna', 'Hollanda donanmasının bir zaferine'], 'Dönemin amblem kitaplarında aşk, sevgiliyi denizde bir gemiye benzeterek anlatılırdı. Durgun deniz umudu, fırtına ise aşkın tehlikelerini çağrıştırırdı.'),
  ('Jan Steen ve Frans van Mieris gibi ressamların tür sahnelerinde bir kadının istiridye yemesi ya da istiridye sunması genellikle neyi çağrıştırır?', 'Şehvet ve cinsel davet', ['Yoksulluk ve açlık', 'Uzun yolculuk ve deniz ticareti', 'Oruç ve dinsel perhiz'], 'İstiridye o dönemde güçlü bir aşk uyarıcısı olarak bilinirdi. Ressamlar bu nesneyi seyirciye ince bir mizah ve ahlak dersiyle sunardı.'),
  ('Leon Battista Alberti \'Resim Üzerine\' adlı kitabında ressamın en yüksek hedefi olarak \'istoria\'yı gösterir. Bu kavram neyi anlatır?', 'Figürlerin jest ve ifadeleriyle duyguları aktaran anlatı sahnesini', ['Yalnız tek bir kişinin yüzünü gösteren portreyi', 'Duvarı süsleyen soyut geometrik bezemeyi', 'Figürsüz, yalnızca doğayı ve gökyüzünü gösteren geniş bir manzarayı'], 'Alberti\'ye göre iyi bir istoria, çeşitli ama ölçülü figürlerle izleyiciyi duygusal olarak etkiler. Bu düşünce, sonraki yüzyıllarda tarih resminin en saygın tür sayılmasının temelini attı.'),
  ('Giorgio Vasari \'Sanatçıların Yaşamları\'nda sanatın gelişimini üç döneme ayırır. Vasari\'ye göre bu gelişmenin doruğunu temsil eden sanatçı kimdir?', 'Michelangelo', ['Giotto', 'Masaccio', 'Jan van Eyck'], 'Vasari\'de Giotto ilk, Masaccio ikinci dönemin öncüsüdür; üçüncü dönem Leonardo, Raffaello ve özellikle Michelangelo ile kusursuzluğa ulaşır. Vasari, Michelangelo\'yu doğayı ve antikleri bile aşan bir usta olarak sunar.'),
  ('Castiglione\'nin \'Saray Adamı\'nda övdüğü \'sprezzatura\' kavramı, Raffaello\'nun resmi için sıkça kullanılır. Bu kavram resimde hangi niteliğe karşılık gelir?', 'Büyük ustalığın emek izi göstermeden kolayca yapılmış gibi görünmesi', ['Fırça izlerinin kalın, kabarık ve her yerde görünür biçimde bırakılması', 'Figürlerin bilerek çirkin ve kusurlu gösterilmesi', 'Resmin yalnız pahalı pigmentlerle boyanması'], 'Sprezzatura, zorluğu gizleyen zarif bir doğallıktır. Vasari ve çağdaşları, Raffaello\'nun kompozisyonlarındaki akıcılığı bu idealin resimdeki karşılığı olarak gördü.'),
  ('Karel van Mander\'in 1604\'te yayımladığı \'Ressamlar Kitabı\' (Schilder-boeck) sanat tarihi yazımı açısından neden önemlidir?', 'Kuzeyli ressamların yaşamlarını Vasari örneğinde toplayan ilk kapsamlı kaynak olması', ['Yağlı boyanın kimyasal formülünü ve kuruma süresini ilk kez ayrıntılı açıklayan kitap olması', 'Hollanda\'daki bütün kilise resimlerinin envanterini çıkarması', 'İtalyan ressamları eleştiren ilk Protestan broşürü olması'], 'Van Mander, Flaman ve Hollandalı ressamlar hakkında bugün bildiklerimizin önemli bir bölümünü kayda geçirdi. Bruegel\'in köylü düğünlerine katıldığı anlatısı da ondan gelir.'),
  ('Jacob Burckhardt\'ın 1860\'ta yayımladığı \'İtalya\'da Rönesans Kültürü\' adlı eserinde Rönesans\'ın belirleyici özelliği olarak öne çıkardığı düşünce hangisidir?', 'Bireyin kendini ayrı bir kişilik olarak keşfetmesi', ['Kilisenin sanat ve düşünce üzerindeki denetiminin giderek artması', 'Feodal düzenin güçlenerek kentleri yönetmesi', 'Antik çağ bilgisinin tümüyle reddedilmesi'], 'Burckhardt\'a göre Orta Çağ insanı kendini topluluk üyesi olarak görürken Rönesans insanı bireyliğini keşfetti. Bu yorum sonradan eleştirilse de dönemin algısını derinden biçimlendirdi.'),
  ('Erwin Panofsky\'nin Erken Hollanda resmi için kullandığı \'gizli simgecilik\' kavramı neyi anlatır?', 'Gerçekçi gündelik nesnelerin aynı zamanda dinsel anlam taşıması', ['Ressamların imzalarını resimdeki nesnelerin içine saklaması', 'Tabloların altına sonradan yeni konular boyanması', 'Yalnızca saray çevresinin anlayabileceği şifreli yazılar kullanılması'], 'Mérode Sunağı\'ndaki zambak ya da Arnolfini Portresi\'ndeki tek mum gibi ayrıntılar hem odanın doğal parçası hem de bir simgedir. Kavram, bu anlamların ne kadar bilinçli olduğu konusunda tartışma da yaratmıştır.'),
  ('Floransalı bankacı Cosimo de\' Medici\'nin San Marco Manastırı gibi dinsel yapılara büyük sanat bağışları yapmasının en olası nedenlerinden biri hangisidir?', 'Faizle kazanılan serveti dinsel hayırla meşrulaştırıp aile prestijini artırmak', ['Floransa yasalarının zenginlere zorunlu sanat vergisi koyması', 'Kilisenin ona Avrupa\'daki bankacılık tekelini yasal olarak vermesi karşılığında', 'Manastırları ticari depo olarak kullanma isteği'], 'Kilise faizciliği günah sayıyordu. Bağışlar hem vicdani bir kefaret hem de Medici adını kentin her köşesinde görünür kılan bir siyasi yatırım işlevi gördü.'),
  ('Papa II. Julius\'un aynı yıllarda Michelangelo\'ya Sistina tavanını, Raffaello\'ya Vatikan odalarını ısmarlaması ve Aziz Petrus Bazilikası\'nın yeniden yapımını başlatması hangi amaca hizmet ediyordu?', 'Roma\'yı ve papalığı antik imparatorluk görkemine yakışır biçimde yüceltmek', ['Papalık hazinesini sanat eserlerine yatırarak enflasyondan korumak', 'Sanatçıları Floransa\'ya karşı ayaklanmaya kışkırtmak', 'Kiliseyi Protestanlarla uzlaştırmak için ortak ve tarafsız bir sanat dili kurmak'], 'II. Julius kendini yeni bir Sezar gibi görüyordu. Sanat programları, papalığın hem dinsel hem siyasi otoritesini görünür kılmayı amaçladı.'),
  ('16. ve 17. yüzyılda prenslerin ve bilginlerin deniz kabukları, fosiller, bilimsel aletler, egzotik nesneler ve sanat eserlerini aynı odada topladıkları koleksiyon biçimi hangi düşünceyi yansıtır?', 'Dünyanın bütün çeşitliliğini küçük bir mekânda toplama ve sınıflama isteğini', ['Yalnız dinsel kalıntıları korumaya ve onlara tapınmaya yönelik bir ibadet anlayışını', 'Sanat eserlerini satmak için kurulmuş bir pazar düzenini', 'Askerî ganimetleri halka teşhir etme geleneğini'], 'Kunstkammer ya da merak kabineleri, doğa ile insan yapımı eserleri birlikte sergileyerek evrenin bir özetini sunmayı amaçladı. Modern müzelerin öncülleri sayılır.'),
  ('Bir öğrenci \'Rönesans sanatçıları antik sanatı yalnızca kopyaladılar\' diyor. Aşağıdakilerden hangisi bu görüşü en güçlü biçimde çürütür?', 'Antik çağda sistemli olarak bilinmeyen doğrusal perspektifi geliştirmeleri', ['Antik heykelleri ölçüp çizerek incelemeleri', 'Mitolojik konuları ve antik tanrıları resimde yeniden canlandırmaları', 'Roma mimari öğelerini yapılarında kullanmaları'], 'Diğer seçenekler antikle bağlılığı gösterir. Matematiksel doğrusal perspektif ise Rönesans\'ın kendi buluşudur ve kopyacılık iddiasını zayıflatır.'),
  ('Michelangelo\'nun \'Son Yargı\'sına sonradan eklenen örtülerin restorasyonda kaldırılıp kaldırılmaması tartışılmıştır. Örtülerin bir kısmının korunmasını savunanların en güçlü gerekçesi hangisidir?', 'Örtülerin de eserin geçirdiği tarihin belgesi olması', ['Örtülerin Michelangelo\'nun kendi eli olması', 'Örtülerin fresği güneş ışığından koruması', 'Örtülerin kaldırılmasının yasalarca yasaklanmış olması'], 'Restorasyon kuramında bir eserin zaman içindeki değişimleri de tarihsel tanıklık sayılır. Bu nedenle 16. yüzyıl örtülerinin bazıları Karşı Reform döneminin belgesi olarak bırakıldı.'),
  ('Bir müze, bir sunak resminin büyük bir ustanın kendi eli mi yoksa atölyesinin işi mi olduğunu belirlemek istiyor. Aşağıdakilerden hangisi en güçlü kanıtı sağlar?', 'Belgelenmiş sözleşme kaydı ile teknik incelemenin aynı sonucu göstermesi', ['Tablonun güzel ve ustalıklı olduğu konusunda uzmanların hemfikir olması', 'Tablonun bir zamanlar ünlü bir koleksiyonda bulunması', 'Çerçevenin ustanın dönemine ait olması'], 'Arşiv belgeleri ve alt çizim, boya katmanları gibi teknik veriler birbirini doğruladığında atıf en sağlam hâlini alır. Beğeni ve koleksiyon geçmişi tek başına yeterli değildir.'),
  ('Andrea del Castagno Yudas\'ı masanın öbür yanında tek başına oturturken, Leonardo \'Son Akşam Yemeği\'nde onu nasıl ayırt eder?', 'Diğer havarilerle aynı yanda, ama geriye çekilmiş, yüzü gölgede ve elinde kese ile', ['Başının üzerine kara bir hale koyup onu diğerlerinden ayırarak', 'Masanın altında sürünür biçimde göstererek', 'Sırtı izleyiciye dönük, yüzü hiç görünmeden'], 'Leonardo, Yudas\'ı ayırmak için geleneksel yalıtma yöntemini bırakır. Işıktan uzak yüzü ve otuz gümüşü çağrıştıran kesesi, onu kalabalığın içinde tanınır kılar.'),
  ('Domenico Ghirlandaio\'nun Louvre\'daki portresinde, yaşlı bir adamın burnundaki şişkin, yumrulu deri hiç gizlenmeden gösterilirken, küçük torunu ona sevgiyle bakar. Bu tercih neyi yansıtır?', 'Fiziksel kusura rağmen sevgi bağını vurgulayan gerçekçi bir bakışı', ['Yaşlı adamla alay etmek için yapılmış bir karikatürü', 'Ressamın tıp kitapları için bir deri hastalığını belgelemesini', 'Torunun dedesinden korktuğunu gösteren bir uyarıyı'], 'Kusurun dürüstçe gösterilmesi, çocuğun bakışındaki şefkati daha da güçlendirir. Portre Rönesans\'ın bireye ve duyguya yönelen ilgisinin dokunaklı bir örneğidir.'),
  ('Leonardo\'nun \'Kakımlı Kadın\' portresinde modelin kucağındaki kakım hem saflığın simgesidir hem de bir kişiye gönderme yapar. Bu kişi kimdir?', 'Modelin sevgilisi Ludovico Sforza', ['Floransa\'nın yöneticisi Lorenzo de\' Medici', 'Fransa Kralı XII. Louis', 'Leonardo\'nun hocası Verrocchio'], 'Ludovico Sforza\'ya Napoli kralı tarafından \'Kakım Nişanı\' verilmişti ve \'beyaz kakım\' lakabıyla anılıyordu. Model Cecilia Gallerani onun gözdesiydi.'),
  ('Bernini\'nin \'Apollon ve Daphne\' grubunun kaidesine Kardinal Maffeo Barberini, \'geçici zevklerin peşine düşen eline yalnız acı yapraklar alır\' anlamında Latince bir dize ekletmiştir. Bu eklemenin amacı nedir?', 'Pagan ve duygusal bir konuyu ahlaki bir derse dönüştürmek', ['Heykelin satış fiyatını kaidede belirtmek', 'Bernini\'nin adını gelecek kuşaklara duyurmak', 'Heykelin antik çağda Yunanistan\'dan getirilmiş özgün bir eser olduğunu kanıtlamak'], 'Heykel bir kardinalin villasında duruyordu. Ahlaki dize, çıplak bir mitolojik kovalamacanın dinsel bir çevrede sergilenmesini meşrulaştırdı.'),
  ('Vermeer\'in \'Süt Döken Kadın\' tablosunda ekmeğin ve sepetin üzerine serpiştirilmiş küçük, açık renkli boya noktacıkları nasıl bir etki yaratır?', 'Işığın yüzeylerde parıldadığı canlı bir doku', ['Tablonun sonradan kirlendiği izlenimi', 'Sahnenin gece geçtiği duygusu', 'Nesnelerin soyut geometrik biçimlere dönüşmesi'], 'Vermeer ışık değen yüzeyleri bu parlak noktalarla verir. Etki, gözün yakın ışık yansımalarını algılayışına benzer ve tabloya titreşen bir canlılık katar.'),
  ('\'İnci Küpeli Kız\' belirli bir kişinin ısmarlama portresi değil, bir \'tronie\' olarak kabul edilir. Bu ne anlama gelir?', 'İlginç bir yüz ifadesi ya da kostüm tipini gösteren bir çalışma olduğu', ['Ressamın kendi kızının resmî düğün portresi olduğu', 'Bir saray kadınının resmî ve ısmarlama tören portresi olduğu', 'Ölmüş bir kişinin anısına yapılmış bir yas portresi olduğu'], 'Hollanda\'da tronie\'ler egzotik başlıklar, abartılı ifadeler ya da karakter tipleri gösteren yüz çalışmalarıydı ve piyasada satılırdı. Türban ve büyük inci bu türün tipik öğeleridir.'),
  ('Fragonard\'ın \'Salıncak\' tablosunda çalıların arasından bakan genç bir adam salıncaktaki kadının eteğinin altını görürken, gölgede kalan yaşlı bir adam salıncağı arkadan iter. Bu düzen neyi ima eder?', 'Kadının yaşlı adamı aldattığı gizli bir aşk oyununu', ['Bir babanın kızına bahçede salıncak sallamayı öğrettiği aile sahnesini', 'Köy şenliğinde yapılan bir yarışmayı', 'Bir mitolojik tanrının ölümlülerle karşılaşmasını'], 'Tablonun ısmarlayanı, kendisini çalıların arasındaki âşık olarak göstermek istemişti. Uçan pabuç ve sessizliği işaret eden Kupid heykeli de bu çapkın sırrı destekler.'),
  ('Giovanni Battista Piranesi\'nin \'Hayalî Hapishaneler\' gravürlerinde sonsuz merdivenler, köprüler ve dev kemerlerin iç içe geçmesi izleyicide en çok hangi duyguyu uyandırır?', 'Ezici ve ürkütücü, sınırsız bir mekân duygusu', ['Ferah, huzurlu ve aydınlık bir bahçe duygusu', 'Gündelik ve sıcak bir ev içi duygusu', 'Neşeli ve hafif bir şenlik duygusu'], 'Mantıksız ölçekler ve bitmeyen geçitler, mekânın içinde kaybolma duygusu yaratır. Bu gravürler sonradan Romantik \'yüce\' anlayışını ve düşsel mimariyi etkiledi.'),
  ('William Hogarth\'ın 1753\'te yayımladığı \'Güzelliğin Çözümlemesi\' kitabında \'güzellik çizgisi\' olarak tanımladığı biçim hangisidir?', 'S biçimli, dalgalı bir eğri', ['Kusursuz bir düz çizgi', 'Tam bir çember yayı', 'Kırık, sivri köşeli bir zikzak çizgisi'], 'Hogarth\'a göre dalgalı çizgi göze canlılık ve çeşitlilik verir. Bu düşünce Rokoko süslemesinin kıvrımlı dilini kuramsal olarak destekler.'),
  ('Thomas Gainsborough\'nun \'Bay ve Bayan Andrews\' portresinde genç çift tuvalin bir köşesinde dururken resmin büyük kısmını kendilerine ait ekili tarlalar kaplar. Bu kompozisyon neyi vurgular?', 'Toprak mülkiyetiyle gelen toplumsal statüyü', ['Çiftin aslında toprağı işleyen yoksul köylüler olduğunu', 'Doğanın insanlara düşman olduğunu', 'Ressamın portre yapmayı sevmediğini'], '18. yüzyıl İngiltere\'sinde toprak sahipliği soyluluğun temeliydi. Düzenli tarlalar, çiftin zenginliğini ve tarımdaki yenilikleri sergiler.'),
  ('Katmanlı yağlı boya resminde üst katmanların alttakilerden daha yağlı olması gerektiğini söyleyen \'yağlının yağsız üstüne\' kuralının amacı nedir?', 'Kuruyan katmanların çatlamasını önlemek', ['Renklerin daha mat görünmesini sağlamak', 'Boyanın daha çabuk satılabilmesini sağlamak', 'Tuvalin daha ağır olmasını sağlamak'], 'Yağı az olan alt katman daha hızlı ve sert kurur. Üste daha esnek, daha yağlı katmanlar sürülürse resim zamanla hareket ettiğinde çatlamaz.'),
  ('Bir eserde uzun sakallı yaşlı bir keşiş, ucu T biçiminde bir asaya dayanır; yanında bir domuz ve küçük bir çan bulunur. Bu aziz büyük olasılıkla kimdir?', 'Büyük Aziz Antonius', ['Aziz Hieronymus', 'Aziz Petrus', 'Aziz Benedictus'], 'Mısırlı keşiş Antonius\'un tarikatı domuz yetiştirip yağını hastaları tedavide kullanırdı. Isenheim Sunağı\'nın ısmarlandığı Antonitler de onun adını taşır.'),
  ('Bir eserde genç ve hamile Meryem, kendisi de hamile olan yaşlı akrabası Elisabet ile bir kapının önünde kucaklaşır. Bu sahneye ne ad verilir?', 'Ziyaret', ['Müjde', 'Tapınakta Takdim', 'Meryem\'in Doğumu'], 'Elisabet daha sonra Vaftizci Yahya\'yı doğuracaktır. Luka İncili\'nde anlatılan bu buluşma, iki kutsal annenin karşılaşmasını gösterir.'),
  ('Bir Rönesans alegorisinde, bir kürenin ya da tekerleğin üzerinde dengede duran, bazen elinde rüzgârla şişmiş bir yelken tutan kadın figürü hangi kavramı temsil eder?', 'Talih', ['Adalet', 'Ölçülülük', 'Umut'], 'Küre ve tekerlek talihin dönekliğini, yelken ise rüzgâr gibi değişkenliğini anlatır. Machiavelli de Fortuna\'yı insan eylemlerinin yarısını yöneten bir güç olarak tartışmıştır.'),
  ('Andrea Pozzo\'nun Roma\'daki Sant\'Ignazio Kilisesi\'nde, tavan freskinin altındaki zemine yuvarlak bir mermer işaret yerleştirilmiştir. Bu işaretin amacı nedir?', 'Yanılsamanın kusursuz göründüğü bakış noktasını göstermek', ['Ayinde rahibin duracağı yeri işaretlemek', 'Kilisenin kurucusu Ignatius\'un mezarının tam yerini belirtmek', 'Gün ışığının yaz gündönümünde düştüğü yeri göstermek'], 'Quadratura yanılsaması yalnız tek bir göz noktasından doğru görünür. İzleyici başka bir yerden baktığında mimari çarpıklaşır.'),
  ('1968\'de başlatılan Rembrandt Araştırma Projesi\'nin ardından Rembrandt\'a kesin olarak atfedilen tablo sayısı belirgin biçimde azalmıştır. Bu sonuç neyi gösterir?', 'Öğrencilerin üslubunun ustanınkine çok yakın olduğunu', ['Rembrandt\'ın tablolarının çoğunun savaşta yok olduğunu', 'Müzelerin tablolarını gizlice sattığını', 'Rembrandt\'ın aslında çok az resim yaptığını kendi mektuplarında söylediğini'], 'Rembrandt\'ın büyük atölyesinde Ferdinand Bol ve Govert Flinck gibi öğrenciler ustanın tarzında çalıştı. Teknik incelemeler bu eserlerin bir kısmını öğrencilere yeniden atfetti.'),
  ('Michelangelo\'nun Davut\'u, onlarca yıl önce başka heykeltıraşların üzerinde çalışıp yarım bıraktığı dar ve uzun bir mermer bloktan yontulmuştur. Bu durum heykeltıraşa nasıl bir güçlük çıkarmıştır?', 'Figürü bloğun önceden işlenmiş sınırlı biçimine sığdırmayı', ['Mermerin çok yumuşak olduğu için en küçük darbede hemen kırılmasını', 'Bloğun renginin bronz gibi koyu olmasını', 'Heykelin yalnızca oturur biçimde yapılabilmesini'], 'Mermer çıkarmalı bir malzemedir; eksilen parça geri eklenemez. Michelangelo, bloğun derinliği az olduğu için figürü ince ve yandan bakıldığında dar bir duruşla tasarlamak zorunda kaldı.'),
  ('17. yüzyıl Hollandası\'nda ressamların çoğunun yalnızca deniz manzarası, kilise iç mekânı ya da çiçek natürmortu gibi tek bir türde uzmanlaşmasının başlıca nedeni nedir?', 'Kalabalık açık piyasada belirli bir türde ün ve hız kazanmak', ['Loncaların her ressama yalnızca tek bir konuyu yasal olarak ayırması', 'Kilisenin dinsel konuları yalnız yabancı ressamlara vermesi', 'Ressamların başka konuları öğrenecek eğitim alamaması'], 'Binlerce ressamın rekabet ettiği bir pazarda uzmanlaşma, hem teknik ustalığı artırıyor hem de alıcıların aradığı ismi tanınır kılıyordu.'),
  ('17. yüzyıl Hollanda natürmortlarında sık görülen, kabuğu sarmal biçimde yarıya kadar soyulmuş limon hangi iki işlevi birlikte görür?', 'Ressamın doku ustalığını gösterir ve dışı çekici içi ekşi zevkleri simgeler', ['Limon ticaretinin vergisini belgeler ve evin sahibinin adını gizler', 'Yemeğin bittiğini gösterir ve konuklara nazikçe veda edilmesi gerektiğini anlatır', 'Sofranın son tatlı yemeğini gösterir ve evdeki bolluğu ile bereketi simgeler'], 'Parlak kabuk, saydam iç ve sarkan şerit ressama zor bir ustalık sınavı sunar. Aynı zamanda görünüşte çekici ama acı tatlı dünyevi zevklerin bir uyarısı sayılır.'),
  ('Annibale Carracci\'nin Farnese Galerisi tavanında sahneler, tavana çerçeveli tablolar asılmış gibi boyanmıştır; Andrea Pozzo ise Sant\'Ignazio\'da tavanı mimari bir yanılsamayla göğe açar. İki yaklaşım arasındaki temel fark nedir?', 'Carracci sahneleri düz tablolar gibi, Pozzo tek bakış noktalı bir yanılsama olarak sunar', ['Carracci yalnız dinsel, Pozzo yalnız mitolojik konular işler', 'Carracci tavanı yalnız gri tonlarla, Pozzo ise yalnız altın varakla kaplanmış alçı ile süsler', 'Carracci tuvali yapıştırır, Pozzo ise mozaik kullanır'], '\'Quadro riportato\' (aktarılmış tablo) sahneleri izleyiciye düzgün bir resim gibi gösterir. Quadratura ise mimariyi aşağıdan bakan göze göre kısaltarak tavanı ortadan kaldırır.'),
  ('Tiziano\'nun geç dönem tablolarından birinde bir satir bir ağaca baş aşağı asılmış, derisi yüzülmektedir; yakında bir müzisyen kemanımsı bir çalgı çalar. Bu sahne hangi mitolojik öyküyü gösterir?', 'Apollon ve Marsyas', ['Herakles ve Kakus', 'Zeus ve Prometheus', 'Dionysos ve Pentheus'], 'Satir Marsyas, Apollon\'u müzik yarışmasına çağırır ve yenilince cezalandırılır. Konu, ilahi sanatın kibre karşı zaferi olarak yorumlanmıştır.'),
  ('Bir Barok tablosunda keçi bacaklı bir tanrının kovaladığı bir peri, ırmak kıyısında sazlara dönüşür; tanrı bu sazlardan bir flüt yapar. Bu sahne hangi öyküdür?', 'Pan ve Syrinks', ['Apollon ve Daphne', 'Alpheios ve Arethusa', 'Zeus ve İo'], 'Ovidius\'a göre Pan sazlardan farklı uzunlukta borular keserek \'syrinks\' denen çobanpüskülü flütü yapmıştır. Rubens ve Jan Brueghel konuyu birlikte resmetti.'),
  ('Tiziano\'nun \'İhtiyat Alegorisi\'nde üç farklı yaşta erkek başının altında bir kurt, bir aslan ve bir köpek başı yer alır. Bu üçlü düzen neyi anlatır?', 'Geçmişi, şimdiyi ve geleceği', ['Üç İncil yazarını', 'Üç Hristiyan erdemini', 'Venedik\'in üç düşmanını'], 'Yazıt da geçmişten ders alıp şimdiyi akıllıca yöneterek geleceği gözetmeyi öğütler. Yaşlı yüzün Tiziano\'nun kendisi olduğu düşünülür.'),
  ('Raffaello\'nun \'Atina Okulu\' ile Rubens\'in \'Haçın Kaldırılışı\' karşılaştırıldığında aşağıdaki gözlemlerden hangisi doğrudur?', 'Raffaello dengeli bir yatay düzen kurar, Rubens güçlü bir köşegenle hareket yaratır', ['Her ikisi de yalnızca tek bir figür üzerine kuruludur', 'Raffaello karanlık bir zemin, Rubens ise altın varaklı parlak bir zemin kullanır', 'Raffaello\'da figürler kesik, Rubens\'te ise çerçeve içinde kapalıdır'], 'Rönesans kompozisyonları simetri ve yatay-dikey dengeyi, Barok kompozisyonlar ise köşegen gerilimi ve hareketi öne çıkarır.'),
  ('15. yüzyılın ikinci yarısında İtalyan portrelerinde profil görünümden yüzün dörtte üçünün göründüğü ve modelin izleyiciye baktığı düzene geçilmiştir. Bu değişimde en çok hangi geleneğin etkisi görülür?', 'Flaman portreciliğinin', ['Bizans ikona sanatının', 'Antik Mısır duvar resminin', 'Osmanlı minyatürünün'], 'Van Eyck ve Memling gibi ustaların dörtte üç portreleri, Antonello da Messina gibi ressamlar aracılığıyla İtalya\'da yayıldı. Bu düzen modele daha canlı bir psikolojik varlık kazandırdı.'),
  ('Erken Rönesans İtalyan portrelerinin, Piero della Francesca\'nın Montefeltro çifti gibi, katı bir profil görünümüyle yapılmasının kaynaklarından biri hangisidir?', 'Antik Roma sikkeleri ve madalyalar', ['Gotik katedral vitrayları', 'Japon ağaç baskıları', 'Ölüm maskelerinin cepheden dökümleri'], 'İmparator başlarının profilden işlendiği antik sikkeler, hümanist çevrede saygınlık taşıyan bir örnekti. Profil, modelin kalıcı ve anıtsal bir imgesini verir.'),
  ('Rembrandt hiç İtalya\'ya gitmediği hâlde ışık-gölge kullanımında Caravaggio\'nun etkisi görülür. Bu etki ona en olası hangi yolla ulaşmıştır?', 'Utrecht\'li Caravaggist ressamlar aracılığıyla', ['Caravaggio\'nun Amsterdam\'da açtığı atölye aracılığıyla', 'Rubens\'in Rembrandt\'a verdiği özel dersler aracılığıyla', 'Venedik\'ten gelen fresk kopyaları aracılığıyla'], 'Honthorst ve Ter Brugghen gibi Roma\'da çalışmış Utrecht\'li ressamlar, Caravaggio\'nun dramatik ışığını Hollanda\'ya taşıdı. Genç Rembrandt bu etkiyi Leiden\'deki eserlerinde gösterir.'),
  ('Bir öğrenci \'Hollanda Altın Çağı resmi gördüğünü yalnızca fotoğraf gibi kopyalar, başka bir anlam taşımaz\' diyor. Bu görüşe yöneltilebilecek en güçlü itiraz hangisidir?', 'Gündelik nesne ve sahnelerin çoğu zaman simgesel ve ahlaki anlamlar taşıması', ['Tabloların çoğunun dinsel sunak resmi olması', 'Hollandalı ressamların aslında hiç gerçekçi, gözleme dayalı resim yapmamış olması', 'O dönemde fotoğraf makinesinin zaten kullanılıyor olması'], 'Sabun köpüğü, yarım limon, istiridye ya da sönmüş mum gibi ayrıntılar, izleyiciye ahlaki dersler ve gizli mesajlar verir. Gerçekçilik bu anlamların taşıyıcısıdır.'),
  ('\'Barok sanat yalnızca Katolik Kilisesi\'nin propagandasına hizmet etmiştir\' görüşünü en iyi hangi örnek çürütür?', 'Protestan Hollanda\'da piyasa için üretilen portre, manzara ve natürmortlar', ['Il Gesù Kilisesi\'nin tavan freski', 'Bernini\'nin Aziz Petrus Bazilikası\'nda Petrus\'un mezarı üzerine yaptığı bronz baldaken', 'Rubens\'in Anvers Katedrali\'ndeki sunakları'], 'Diğer seçenekler Katolik dinsel sanatın örnekleridir. Hollanda\'nın burjuva pazarı ise Barok çağının dinsel olmayan ve kilise dışı büyük bir sanat üretimini kanıtlar.'),
  ('Caravaggio\'nun bazı sunak resimleri ısmarlayan kiliselerce geri çevrilmiş, ama hemen ardından seçkin koleksiyoncular tarafından satın alınmıştır. Bu durum neyi gösterir?', 'Kilisenin uygunluk ararken koleksiyoncuların sanatsal yeniliğe değer verdiğini', ['Koleksiyoncuların dinsel resimlere hiç ilgi duymadığını', 'Caravaggio\'nun tablolarını bilerek kiliselere düşük fiyata satıp sonra geri alması', 'Kilisenin tabloları sonradan gizlice geri aldığını'], 'Rahipler kutsal figürlerin saygınlığını korumak isterken Mantova Dükü ya da Kardinal Borghese gibi alıcılar Caravaggio\'nun cesur gerçekçiliğini koleksiyonlarına katmak istedi.'),
  ('Yüksek Rönesans ustalarının sanatı kusursuzluğa ulaştırdığı düşüncesi, sonraki kuşak ressamlarını nasıl bir yöne itmiştir?', 'Doğayı değil ustaların üslubunu aşmaya çalışan yapay ve karmaşık bir sanata', ['Gotik altın zeminli resme bilinçli olarak geri dönmeye', 'Bütün süslemeyi ve figürü bırakıp yalnızca geometrik soyutlamaya yönelmeye', 'Yalnızca natürmort ve manzara türlerine çekilmeye'], 'Leonardo, Raffaello ve Michelangelo\'nun ardından gelen ressamlar, ustaların başarılarını abartılı oranlar, beklenmedik renkler ve karmaşık pozlarla yeniden yorumladı. Maniyerizm bu çabanın ürünüdür.'),
  ('XIV. Louis\'nin 1715\'teki ölümünden sonra soyluların Versailles\'dan Paris\'teki konaklarına dönmesi, resmin ölçeğini ve havasını nasıl etkilemiştir?', 'Küçük ve samimi salonlara uygun, daha hafif ve küçük eserler öne çıkmıştır', ['Dinsel sunak resimleri saray resminin yerini almıştır', 'Dev boyutlu savaş tabloları ve kralı yücelten görkemli tören portreleri çoğalmıştır', 'Resim yerini tümüyle duvar halılarına bırakmıştır'], 'Özel konakların zarif salonları, oda boyutuna uygun aşk sahnelerine, pastel portrelere ve dekoratif panolara talep yarattı. Rokoko bu ortamda gelişti.'),
  ('Rogier van der Weyden\'in \'Çarmıhtan İndiriliş\' tablosunda bayılan Meryem\'in bedeni, haçtan indirilen İsa\'nın bedeniyle neredeyse aynı eğriyi çizer. Bu yinelemenin anlamı nedir?', 'Meryem\'in oğlunun acısını kendi bedeninde paylaşması', ['Meryem\'in de o gün öldüğünün gösterilmesi', 'Ressamın aynı modeli iki kez kullanmak zorunda kalması', 'İki figürün ayrı panolarda olduğu izlenimi vermek'], 'Bu biçimsel yankı \'compassio\' denen ortak acı düşüncesini görselleştirir. İzleyici de bu acıya ortak olmaya çağrılır.'),
  ('Artemisia Gentileschi\'nin \'Holofernes\'in Başını Kesen Yudit\'i, Caravaggio\'nun aynı konudaki tablosuyla karşılaştırıldığında en çok hangi yönüyle ayrılır?', 'Kadınların işe kararlılıkla ve fiziksel güçle girişmesiyle', ['Holofernes\'in hiç gösterilmemesiyle', 'Sahnenin gündüz, açık havada ve kalabalık bir ordunun önünde geçmesiyle', 'Yudit\'in bir melek tarafından yönlendirilmesiyle'], 'Caravaggio\'nun Yudit\'i kolları uzanmış, yüzü tiksinti dolu, çekingen bir genç kızdır. Artemisia\'da ise Yudit ve hizmetçisi adamı birlikte bastırır; sahnenin fiziksel gerçekliği çok daha yoğundur.'),
  ('Botticelli\'nin figürleri ile Leonardo\'nun figürleri karşılaştırıldığında biçimi oluşturma yöntemleri bakımından hangi ayrım doğrudur?', 'Botticelli belirgin akıcı konturlar çizer, Leonardo konturu yumuşak geçişlerle eritir', ['İkisi de figürleri altın zemin üzerinde düz renklerle boyar', 'Botticelli yalnızca gölgelerle, Leonardo ise yalnızca keskin kontur çizgileriyle çalışır', 'Botticelli kalın boya katmanları, Leonardo ise kolaj kullanır'], 'Botticelli\'nin zarif çizgisi Floransa\'nın disegno geleneğini sürdürür. Leonardo ise sfumato ile biçimin kenarlarını havaya karıştırarak daha doğal bir hacim yanılsaması kurar.'),
  ('Brancacci Şapeli\'nde Masaccio\'nun \'Cennetten Kovuluş\'u ile Masolino\'nun \'Âdem ile Havva\'nın Günahı\' karşılaştırıldığında Masaccio\'nun figürlerini ayıran özellik hangisidir?', 'Tek yönden gelen ışıkla gölge düşüren ağır bedenler ve yoğun acı ifadesi', ['Arka planda ayrıntılı bir Flaman manzarası ve çiçekli çayırlar', 'Altın varakla süslenmiş zarif giysiler, sakin ve gülümseyen yüzler, süslü bir bahçe', 'Figürlerin yalnızca kontur çizgileriyle ve renksiz bırakılması'], 'Masaccio, şapelin gerçek penceresinden gelen ışığı hesaba katarak figürlere hacim ve ağırlık verdi. Masolino\'nun figürleri ise daha zarif ve duygusal olarak durgundur.'),
  ('Paolo Uccello\'nun \'San Romano Savaşı\' panolarında yere düşmüş mızrakların ve devrilmiş bir askerin bedeninin derinliğe doğru düzenli biçimde dizilmesi neyi gösterir?', 'Ressamın perspektif ızgarasını sahneye bilinçli olarak yerleştirdiğini', ['Panoların sonradan başka bir ressamca tamamlandığını', 'Savaşın gerçekte kanlı bir çatışma değil, kentin düzenlediği bir tören alayı olduğunu', 'Ressamın savaş sahnesine bizzat katıldığını'], 'Savaşın kargaşası içinde bile mızraklar ve beden, kaçış noktasına yönelen çizgiler gibi yerleştirilmiştir. Bu, Uccello\'nun perspektife duyduğu tutkunun görsel izidir.'),
  ('Tiziano\'nun \'Urbino Venüsü\'nü, Giorgione\'nin açık havada uyuyan \'Uyuyan Venüs\'ünden ayıran temel fark hangisidir?', 'Uyanık, izleyiciye doğrudan bakan ve bir saray odasında yatan bir kadın olması', ['Sahnenin gece ve mum ışığında geçmesi', 'Figürün giyinik, ayakta ve bir mitolojik öykünün ortasında gösterilmesi', 'Kadının yerine genç bir erkeğin konması'], 'Tiziano, Giorgione\'nin kırsal ve rüya gibi tanrıçasını bir iç mekâna taşıdı. Arka plandaki hizmetçiler ve sandık, sahneye gündelik ve evlilikle ilgili bir bağlam kazandırır.'),
  ('Barok tavan resimlerinde mimari yanılsamayı uzman bir \'quadraturista\' çizerken figürlerin başka bir ressam tarafından boyanması neyi gösterir?', 'Büyük işlerde uzmanlığa dayalı bir iş bölümü yapıldığını', ['Figür ressamlarının perspektif bilmediğini', 'Tavanların her zaman iki ayrı dönemde boyandığını', 'Kilisenin iki ressama eşit ücret vermeyi zorunlu kıldığını'], 'Perspektifli mimari ayrı bir uzmanlık alanıydı. Bolonyalı quadratura ustaları ile figür ressamları birçok sarayda ve kilisede birlikte çalıştı.'),
  ('Ghiberti, Floransa Vaftizhanesi\'nin kuzey kapılarına 1403\'te başlayıp 1424\'te bitirmiş, doğu kapılarına ise 1425\'te başlayıp 1452\'de bitirmiştir. İki kapının yapımı toplam kaç yıl sürmüştür?', '48', ['38', '42', '52'], 'Kuzey kapıları 1424 - 1403 = 21 yıl, doğu kapıları 1452 - 1425 = 27 yıl sürdü. Toplam 21 + 27 = 48 yıl eder; Ghiberti yaşamının büyük bölümünü bu kapılara adamıştır.'),
  ('Doğrusal perspektifte görünen boy uzaklıkla ters orantılıdır. 5 metre uzaktaki bir figür resimde 10 cm boyunda görünüyorsa, aynı boydaki başka bir figür 10 metre uzakta yaklaşık kaç cm görünür?', '5 cm', ['2,5 cm', '10 cm', '20 cm'], 'Uzaklık iki katına çıkınca görünen boy yarıya iner: 10 cm × 5 / 10 = 5 cm. Bu ilke, Alberti\'nin anlattığı perspektif kuruluşunun temelidir.'),
  ('Bir kilise sunağı için yapılmış bir Rönesans tablosu bugün bir müzede göz hizasında, beyaz bir duvarda sergileniyor. Bu yer değiştirme eserin algılanışını nasıl etkiler?', 'İbadet işlevinden ve özgün ışığından koparılarak bir sanat nesnesi olarak görülür', ['Eser daha çok bir ibadet nesnesine dönüşür', 'Eserin anlamı, etkisi ve işlevi hiçbir biçimde değişmeden aynen korunur', 'Eserin renkleri kimyasal olarak değişir'], 'Sunak resimleri yüksekte, mum ışığında ve ayinle birlikte görülmek üzere tasarlanmıştı. Müze ortamı ise biçimsel ve tarihsel incelemeyi öne çıkarır.'),
  ('Rönesans ve Barok \'Son Yargı\' resimlerinde kurtulanlar, ortada yargıç olarak oturan İsa\'nın genellikle hangi yanında gösterilir?', 'İsa\'nın sağında, yani izleyicinin solunda', ['İsa\'nın solunda, yani izleyicinin sağında', 'Yalnızca İsa\'nın ayaklarının dibinde', 'Resmin en altında, mezarlar arasında'], 'Sağ taraf geleneksel olarak onur ve kutsanmışlık yönüdür. Lanetliler ise İsa\'nın soluna, yani izleyicinin sağına düşer; Michelangelo\'nun Son Yargı\'sı da bu düzeni izler.'),
  ('Tiziano\'nun bir tablosunda tanrıça Diana, yıkanırken perilerinden birinin hamile olduğunu fark eder ve onu öfkeyle kovar; öteki periler genç kızın giysisini çekip gerçeği açığa çıkarır. Bu peri kimdir?', 'Kallisto', ['Arethusa', 'Echo', 'Daphne'], 'Zeus tarafından baştan çıkarılan Kallisto, Diana\'nın bekâret yeminli topluluğundan atılır. Tiziano bu öyküyü II. Felipe için yaptığı poesie dizisinde işledi.'),
  ('Annibale Carracci\'nin bir tablosunda genç ve kaslı bir kahraman iki kadın arasında durur: biri onu zevk dolu kolay bir yola, öteki dik ve taşlı bir patikaya çağırır. Bu sahne hangi konudur?', 'Herakles\'in Seçimi', ['Paris\'in Yargısı', 'Odysseus ile Sirenler', 'Theseus ile Ariadne'], 'Antik bir anlatıya göre genç Herakles, Kötülük ile Erdem arasında seçim yapmak zorunda kalır ve zor yolu seçer. Konu, erdemli yaşamın simgesi olarak saray odalarında sevildi.'),
  ('Rönesans resimlerinde sık görülen bir konuda, elinde bir balık taşıyan küçük bir oğlan, yanında yürüyen kanatlı bir melekle birlikte yolculuk eder. Bu konu hangisidir?', 'Tobias ve Melek', ['İshak\'ın Kurbanı', 'Yakup\'un Rüyası', 'Yunus ile Balina'], 'Apokrif Tobit kitabında Başmelek Rafael, genç Tobias\'a yolculuğunda eşlik eder; yakaladıkları balığın safrası babasının körlüğünü iyileştirir. Konu, uzağa giden çocukların korunması dileğiyle ısmarlanırdı.'),
  ('Orta Çağ resminde kutsal figürlerin başının ardında dolu bir altın disk biçiminde gösterilen hale, 15. yüzyıldan sonra çoğu zaman ince, saydam bir halkaya dönüşmüştür. Bu değişimin nedeni nedir?', 'Gerçekçi ve perspektifli mekânla uyum sağlama isteği', ['Altının yasaklanıp pahalanması', 'Kilisenin haleyi tümüyle yasaklaması', 'Ressamların kutsal figürleri tanımaması'], 'Düz altın disk, derinlikli bir mekânda yapay görünür. Ressamlar haleyi perspektifle kısaltılmış ince bir halkaya indirgeyerek kutsallığı doğal görünümle birleştirdi.'),
  ('Caravaggio, Rembrandt ve Velázquez gibi 17. yüzyıl ressamlarının beyaz yerine kırmızımsı ya da kahverengi tonlu zemin üzerine boyamayı yeğlemesinin başlıca yararı nedir?', 'Orta tondan başlayarak ışığı ve gölgeyi hızla kurabilmek', ['Tuvalin daha uzun süre nem çekmesini sağlamak', 'Renklerin tümünü soluk ve pastel göstermek', 'Boyanın tuvalde hiç çatlamamasını garanti etmek'], 'Koyu zemin, gölgeleri hazır verir; ressam yalnızca aydınlık bölümleri kalın açık renklerle ekler. Bu yöntem dramatik ışık-gölge karşıtlığına çok uygundur.'),
  ('Raffaello\'nun Sistina Şapeli için yaptığı halı kartonlarında figürlerin çoğu, örneğin kutsama jestleri, sol elle yapılır. Bunun nedeni nedir?', 'Dokuma sırasında görüntünün ters dönecek olması', ['Raffaello\'nun solak olması', 'Papanın sol eli kutsal sayması', 'Kartonların aynada kopyalanarak çizilmesi'], 'Halı, kartonun arkasından bakılarak dokunduğu için bitmiş halıda görüntü ayna gibi tersine döner. Raffaello bu yüzden kompozisyonları ters çizdi.'),
  ('Raffaello\'nun \'Başkalaşım\' tablosunda üst bölümde ışık içinde yükselen İsa, alt bölümde ise havarilerin iyileştiremediği nöbet geçiren bir oğlan gösterilir. Bu iki katlı düzen neyi vurgular?', 'İnsan çabasının çaresizliği karşısında tanrısal kurtuluşu', ['Havarilerin İsa\'dan daha güçlü olduğunu', 'Tablonun iki farklı ressamca yapıldığını', 'Dağ ile ovanın coğrafi farkını'], 'Aşağıdaki karanlık ve karmaşık kalabalık, yukarıdaki aydınlık ve dingin göğe karşıtlık oluşturur. Bazı havarilerin yukarıyı işaret etmesi iki bölümü birbirine bağlar.'),
  ('Velázquez\'in \'Marta ve Meryem\'in Evinde İsa\' tablosunda ön planda sarımsak döven genç bir hizmetçi görülür; arka planda küçük bir açıklıkta İsa\'yı dinleyen Meryem yer alır. Bu düzen neyi karşılaştırır?', 'Gündelik çalışma ile dinsel tefekkürü', ['Zenginlik ile yoksulluğu', 'Gençlik ile yaşlılığı', 'Kent yaşamı ile köy yaşamını'], 'İncil\'de Marta ev işleriyle uğraşırken Meryem İsa\'yı dinler. Velázquez, bodegón geleneğini bu öyküyle birleştirerek eylemli ve düşünsel yaşamı karşı karşıya getirir.'),
  ('Jan Steen\'in sık işlediği \'Doktor Ziyareti\' sahnelerinde solgun genç bir kadının nabzını tutan doktor gülünç biçimde gösterilir. Bu sahnelerde hastalığın gerçek nedeni genellikle ne olarak ima edilir?', 'Aşk acısı ya da gizli bir gebelik', ['Salgın bir veba hastalığı', 'Zehirlenme sonucu oluşan bir nöbet', 'Ağır bir savaş yarası'], 'Odadaki Kupid tabloları, sönmüş mangallar ya da idrar şişeleri gibi ayrıntılar, izleyiciye doktorun anlamadığı gerçeği fısıldar. Steen bu konuyu mizah ve ahlak dersiyle birleştirir.'),
  ('Vasari\'nin \'Sanatçıların Yaşamları\'nı kaynak olarak kullanan bir araştırmacının dikkat etmesi gereken en önemli nokta hangisidir?', 'Floransa\'yı öne çıkaran yerel bir bakış taşıması ve anekdotların doğrulanmamış olabilmesi', ['Kitabın yalnız Flaman ressamları anlatması', 'Kitabın 20. yüzyılda yazılmış olması', 'Kitapta hiçbir tarih ve eser adı bulunmaması'], 'Vasari, Floransa ve Michelangelo merkezli bir ilerleme anlatısı kurar; Venedikli ya da Kuzeyli ustalara daha az yer verir. Canlı anekdotlarının bir kısmı da belgelerle doğrulanamaz.'),
  ('Bernini\'nin Aziz Petrus Bazilikası\'ndaki baldakeni için Pantheon\'un girişindeki antik bronz kirişlerin söküldüğü anlatılır. O dönemde dolaşan \'Barbarların yapmadığını Barberiniler yaptı\' sözü neye tepkidir?', 'Antik bir yapının malzemesinin yeni işler için sökülüp eritilmesine', ['Papalığın Roma\'yı yabancı ordulara teslim etmesine', 'Bernini\'nin yabancı bir ressamı işe almasına', 'Pantheon\'un camiye dönüştürülmesine'], 'Barberini ailesinden Papa VIII. Urbanus\'un antik bronzu kullanması, Roma halkınca bir yağma gibi algılandı. Bronzun bir bölümünün top dökümüne gittiği de bilinir.'),
  ('17. yüzyıla ait bir gravürün altında bir sanatçının adının yanında \'invenit\', başka bir sanatçının adının yanında ise \'sculpsit\' yazmaktadır. Bu bilgiye göre hangisi doğrudur?', 'İlki tasarımı yapan, ikincisi levhayı oyan sanatçıdır', ['İlki levhayı oyan, ikincisi baskıyı satan kişidir', 'İkisi de aynı resmin ortak ressamlarıdır', 'İlki eserin sahibi, ikincisi onu kopyalayan kişidir'], 'Röprodüksiyon gravürlerinde \'invenit\' (buldu, tasarladı) özgün kompozisyonun yaratıcısını, \'sculpsit\' (oydu) ise gravürcüyü belirtir.'),
  ('16. yüzyıl Venedik\'inde Scuola Grande di San Rocco gibi kardeşlik kurumlarının binalarını büyük resim döngüleriyle süsletmesinin başlıca amacı neydi?', 'Hayır kurumu olarak dindarlıklarını ve prestijlerini göstermek', ['Binaları sanat okulu olarak kullanmak', 'Resimleri yurt dışına satarak gelir elde etmek', 'Doçların yerine kentin yönetimini almak'], 'Scuole, yardımlaşma ve dinsel ibadet amacıyla kurulmuş zengin yurttaş kardeşlikleriydi. Tintoretto ve Carpaccio\'nun büyük döngüleri bu kurumların gücünü ve hayırseverliğini sergiledi.'),
  ('Holbein\'in \'Elçiler\' tablosunun sol üst köşesinde, yeşil perdenin arkasında yarı gizlenmiş küçük bir çarmıh bulunur. Bu ayrıntı genellikle nasıl yorumlanır?', 'Ölüm ve dünyevi bilginin ötesinde kurtuluş umudunun saklı da olsa var olduğu', ['Ressamın tabloyu bitirmeyi unuttuğu bir bölüm olduğu', 'Elçilerin dinsiz olduğunun açıkça ilan edildiği', 'Perdenin ardında başka bir tablonun saklandığı'], 'Ön plandaki çarpık kafatası ölümü hatırlatırken köşedeki çarmıh, Hristiyan inancına göre ölümün aşılabileceğini ima eder. Tablo, bilgi, iktidar ve ölümlülük arasında katmanlı bir düşünce sunar.'),
  ('\'Kuzey Rönesansı İtalya\'dan tümüyle bağımsız gelişmiştir\' görüşünü en güçlü biçimde çürüten kanıt hangisidir?', 'Dürer\'in Venedik yolculukları ve İtalyan oran kuramlarını incelemesi', ['Van Eyck\'in yağlı boyayı geliştirmesi', 'Bosch\'un düşsel yaratıklar çizmesi', 'Kuzey\'de meşe pano kullanılması'], 'Dürer iki kez Venedik\'e gitti, Giovanni Bellini ile tanıştı ve İtalyan perspektif ile oran bilgisini Kuzey\'e taşıdı. Diğer seçenekler Kuzey\'in kendine özgü gelişmeleridir.'),
  ('Michelangelo\'nun çağdaşlarının onun eserleri karşısında duydukları etkiyi anlatmak için kullandıkları \'terribilità\' kavramı neyi anlatır?', 'İnsanı sarsan, ürkütücü bir güç ve yücelik duygusunu', ['Teknik hatalardan doğan korkunç bir çirkinliği', 'Eserlerin çok hızlı yapılmış olmasını', 'Sanatçının müşterilerine karşı kaba davranışını'], 'Terribilità, Musa heykelinde ya da Son Yargı\'da hissedilen ezici enerjiyi ve dehşet uyandıran büyüklüğü anlatır. Kavram II. Julius\'un kişiliği için de kullanılmıştır.'),
  ('Caravaggio\'dan günümüze neredeyse hiç hazırlık çizimi kalmamıştır; tuvallerinin zemininde ise fırça sapıyla kazınmış ince çizgiler görülür. Bu durum çalışma yöntemi hakkında neyi düşündürür?', 'Modelleri karşısına alıp doğrudan tuvale boyadığını', ['Bütün tablolarını yardımcılarına boyattığını', 'Kompozisyonlarını önceki ustaların gravürlerinden kopyaladığını', 'Yalnızca hafızasından ve hayalinden resim yaptığını'], 'Kazıma izler, modelin konumunu tuvale hızla işaretlemek için kullanılmış olmalıdır. Bu, Rönesans\'ın ayrıntılı çizim ve karton geleneğinden belirgin bir kopuştur.'),
  ('Vermeer, ekonomik sıkıntılar içinde olmasına karşın tablolarında altından pahalı doğal ultramarini bol miktarda, hatta gölgelerin altında bile kullanmıştır. Bu tercih neyi gösterir?', 'Renk etkisinin kalitesine maliyetten daha çok önem verdiğini', ['Ultramarinin o dönemde çok ucuz olduğunu', 'Tablolarının yalnızca mavi tonlardan oluştuğunu', 'Pigmenti ressamlar loncasından bedava aldığını'], 'Ultramarin gölgelere serin ve derin bir parlaklık verir. Vermeer\'in bu pigmenti cömertçe kullanması, ışığa ve renge verdiği önemi ortaya koyar.'),
  ('Botticelli\'nin \'Venüs\'ün Doğuşu\'nda tanrıçanın bir eliyle göğsünü, öbür eliyle saçlarıyla kasığını örttüğü duruş hangi antik heykel tipinden alınmıştır?', 'Utangaç Venüs', ['Uyuyan Ariadne', 'Ayakta duran Kouros', 'Diskobolos'], 'Bu tip, antik Afrodit heykellerinde yaygındı ve Medici koleksiyonundaki bir örnek Floransa\'da biliniyordu. Botticelli antik bir pozu mitolojik bir doğum sahnesine taşıdı.'),
  ('Michelangelo\'nun Vatikan\'daki Pietà\'sında Meryem, kucağındaki yetişkin oğlundan daha genç görünür. Biyografi yazarı Condivi\'ye göre Michelangelo bunu nasıl açıklamıştır?', 'Saflığının onu gençlik içinde koruduğu düşüncesiyle', ['Modelinin genç bir kız olmasıyla', 'Mermer bloğun küçük olmasıyla', 'Papanın yaşlı yüzleri yasaklamasıyla'], 'Michelangelo, lekesiz bir kadının yaşın izlerini taşımayacağını söylemiştir. Bu ideal güzellik anlayışı heykelin dingin havasını açıklar.'),
  ('Bernini\'nin \'Azize Teresa\'nın Vecdi\' ile Michelangelo\'nun Vatikan Pietà\'sı karşılaştırıldığında, iki heykelin izleyiciyle kurduğu ilişki bakımından hangi fark öne çıkar?', 'Bernini ışık ve mimariyle izleyiciyi bir sahnenin içine çekerken Michelangelo kapalı ve dingin bir bütün sunar', ['Michelangelo heykeli renkli mermerle boyarken Bernini tümüyle beyaz bırakır', 'İkisi de yalnızca arkadan izlenmek üzere tasarlanmıştır', 'Bernini figürleri kesin bir cephesellikle dizerken Michelangelo onları sarmal biçimde döndürür'], 'Pietà sakin piramidal bir biçim içinde kendine yeter. Teresa grubu ise gizli ışık, yaldızlı ışınlar ve tiyatro locası gibi duvarlarla izleyiciyi dramın tanığı yapar.'),
  ('Bir Barok tablosunda yaşlı ve sakallı bir havari, bir horozun ötüşünü duyunca ellerini kavuşturup ağlamaktadır. Bu sahne hangi olaya gönderme yapar?', 'Petrus\'un İsa\'yı inkâr etmesi', ['Tomas\'ın şüphesi', 'Yudas\'ın ihaneti', 'Pavlus\'un dönüşümü'], 'İsa, Petrus\'un horoz ötmeden önce onu üç kez inkâr edeceğini söylemişti. Horoz bu nedenle Petrus\'un pişmanlığının simgesi olarak tablolarda yer alır.'),
];
